! (`print *, f()`), where flushing output_unit would be recursive I/O (gfortran deadlocks).
logical, private :: rs_in_function = .false.
logical, private :: rs_ready = .false., rs_raised = .false.
character(len=:), allocatable, private :: rs_raised_message
procedure(rs_dispatch_iface), pointer :: rs_callback_dispatch => null(), rs_override_dispatch => null()
procedure(rs_name_iface), pointer :: rs_class_name_fn => null()

