! ---------------------------------------------------------------- native references
recursive function rs_new_entry(holder, klass, kind) result(slot)
    integer(c_int64_t), intent(in) :: holder
    integer, intent(in) :: klass, kind
    integer :: slot
    type(rs_entry), allocatable :: grown(:)
    integer, allocatable :: free(:)
    if (.not. allocated(rs_entries)) then
        allocate(rs_entries(256), rs_free(256))
    end if
    if (rs_nfree > 0) then
        slot = rs_free(rs_nfree)
        rs_nfree = rs_nfree - 1
    else
        if (rs_used == size(rs_entries)) then
            allocate(grown(2 * size(rs_entries)))
            grown(1:rs_used) = rs_entries(1:rs_used)
            call move_alloc(grown, rs_entries)
            allocate(free(size(rs_entries)))
            free(1:rs_nfree) = rs_free(1:rs_nfree)
            call move_alloc(free, rs_free)
        end if
        rs_used = rs_used + 1
        slot = rs_used
    end if
    rs_keys = int(modulo(int(rs_keys, c_int64_t) * 1103515245_c_int64_t + 12345_c_int64_t, 2147483646_c_int64_t)) + 1
    rs_entries(slot) = rs_entry(holder, rs_keys, 1, 0, klass, 0, 0, kind, null())
end function

recursive logical function rs_valid(slot, key)
    integer, intent(in) :: slot, key
    rs_valid = .false.
    if (.not. allocated(rs_entries)) return
    if (slot < 1 .or. slot > rs_used) return
    rs_valid = rs_entries(slot)%key == key .and. rs_entries(slot)%kind /= 0 .and. key /= 0
end function

! Drops one Fortran reference; the entry goes when neither Fortran nor C++ refers to it.
recursive subroutine rs_drop(slot)
    integer, intent(in) :: slot
    if (slot < 1 .or. slot > rs_used) return
    if (rs_entries(slot)%kind == 0) return
    rs_entries(slot)%count = rs_entries(slot)%count - 1
    if (rs_entries(slot)%count <= 0 .and. rs_entries(slot)%retained <= 0) call rs_release_entry(slot)
end subroutine

recursive subroutine rs_release_entry(slot)
    integer, intent(in) :: slot
    integer(c_int64_t) :: holder
    integer :: parent
    holder = rs_entries(slot)%holder
    parent = rs_entries(slot)%parent
    rs_entries(slot)%holder = 0
    rs_entries(slot)%kind = 0
    rs_entries(slot)%key = 0
    rs_entries(slot)%self => null()
    rs_nfree = rs_nfree + 1
    rs_free(rs_nfree) = slot
    if (holder /= 0) call rs_c_release(holder, merge(0_c_int, 1_c_int, rs_depth > 0))
    if (parent /= 0) call rs_drop(parent)
end subroutine

recursive subroutine rs_object_assign(a, b)
    class(rosetta_object), intent(inout) :: a
    class(rosetta_object), intent(in) :: b
    integer :: old, old_key
    old = a%rs_slot
    old_key = a%rs_key
    if (rs_valid(b%rs_slot, b%rs_key)) then
        rs_entries(b%rs_slot)%count = rs_entries(b%rs_slot)%count + 1
        a%rs_slot = b%rs_slot
        a%rs_key = b%rs_key
    else
        a%rs_slot = 0
        a%rs_key = 0
    end if
    if (rs_valid(old, old_key)) call rs_drop(old)
end subroutine

recursive subroutine rs_object_final(self)
    type(rosetta_object), intent(inout) :: self
    if (rs_valid(self%rs_slot, self%rs_key)) call rs_drop(self%rs_slot)
    self%rs_slot = 0
    self%rs_key = 0
end subroutine

recursive subroutine rs_object_close(self)
    class(rosetta_object), intent(inout) :: self
    integer(c_int64_t) :: holder
    if (.not. rs_valid(self%rs_slot, self%rs_key)) return
    holder = rs_entries(self%rs_slot)%holder
    rs_entries(self%rs_slot)%holder = 0
    if (holder /= 0) call rs_c_release(holder, merge(0_c_int, 1_c_int, rs_depth > 0))
end subroutine

recursive logical function rs_object_is_closed(self)
    class(rosetta_object), intent(in) :: self
    rs_object_is_closed = .true.
    if (rs_valid(self%rs_slot, self%rs_key)) rs_object_is_closed = rs_entries(self%rs_slot)%holder == 0
end function

recursive function rs_object_class_name(self) result(name)
    class(rosetta_object), intent(in) :: self
    character(len=:), allocatable :: name
    name = 'closed native object'
    if (.not. rs_valid(self%rs_slot, self%rs_key)) return
    if (rs_entries(self%rs_slot)%holder == 0) return
    if (associated(rs_class_name_fn)) then
        name = rs_class_name_fn(rs_entries(self%rs_slot)%klass)
    else
        name = 'native object'
    end if
end function

!> Whether `a` and `b` refer to the same C++ object.
recursive logical function rosetta_same(a, b)
    class(rosetta_object), intent(in) :: a, b
    rosetta_same = .false.
    if (.not. rs_valid(a%rs_slot, a%rs_key) .or. .not. rs_valid(b%rs_slot, b%rs_key)) return
    if (a%rs_slot == b%rs_slot) then
        rosetta_same = .true.
    else
        rosetta_same = rs_entries(a%rs_slot)%holder /= 0 .and. &
            rs_entries(a%rs_slot)%holder == rs_entries(b%rs_slot)%holder
    end if
end function

!> Reports an error from Fortran code that C++ called (a callback, or an overriding method of a
!> director): when it returns, C++ raises the error, and the Fortran call that reached C++ fails
!> with `message` (status code 2, kind `fortran`).
recursive subroutine rosetta_raise(message)
    character(len=*), intent(in) :: message
    rs_raised = .true.
    rs_raised_message = message
end subroutine

! The slot of an object (0 when unset or invalid).
recursive integer function rs_slot_of(o)
    class(rosetta_object), intent(in) :: o
    rs_slot_of = 0
    if (rs_valid(o%rs_slot, o%rs_key)) rs_slot_of = o%rs_slot
end function

! Makes `o` refer to `slot`, which already counts this reference.
recursive subroutine rs_set(o, slot)
    class(rosetta_object), intent(inout) :: o
    integer, intent(in) :: slot
    if (rs_valid(o%rs_slot, o%rs_key)) call rs_drop(o%rs_slot)
    o%rs_slot = slot
    o%rs_key = 0
    if (slot > 0) o%rs_key = rs_entries(slot)%key
end subroutine

! A director object: a new entry pointing at `self` (which must stay at its address); its id goes
! to the C++ constructor, and rs_adopt stores the C++ object it creates.
recursive function rs_attach(self) result(id)
    class(rosetta_object), target, intent(inout) :: self
    integer :: id
    id = rs_new_entry(0_c_int64_t, -1, 1)
    rs_entries(id)%self => self
    call rs_set(self, id)
end function

! ---------------------------------------------------------------- encoding
recursive subroutine rs_reserve(w, extra)
    type(rs_writer), intent(inout) :: w
    integer, intent(in) :: extra
    integer(c_int8_t), allocatable :: grown(:)
    if (.not. allocated(w%d)) allocate(w%d(max(256, extra)))
    if (w%n + extra <= size(w%d)) return
    allocate(grown(max(2 * size(w%d), w%n + extra)))
    grown(1:w%n) = w%d(1:w%n)
    call move_alloc(grown, w%d)
end subroutine

recursive subroutine rs_u8(w, value)
    type(rs_writer), intent(inout) :: w
    integer, intent(in) :: value
    call rs_reserve(w, 1)
    w%n = w%n + 1
    w%d(w%n) = int(value, c_int8_t)
end subroutine

recursive subroutine rs_u32(w, value)
    type(rs_writer), intent(inout) :: w
    integer, intent(in) :: value
    call rs_reserve(w, 4)
    w%d(w%n + 1:w%n + 4) = transfer(int(value, c_int32_t), 0_c_int8_t, 4)
    w%n = w%n + 4
end subroutine

recursive subroutine rs_u64(w, value)
    type(rs_writer), intent(inout) :: w
    integer(c_int64_t), intent(in) :: value
    call rs_reserve(w, 8)
    w%d(w%n + 1:w%n + 8) = transfer(value, 0_c_int8_t, 8)
    w%n = w%n + 8
end subroutine

recursive subroutine rs_f64(w, value)
    type(rs_writer), intent(inout) :: w
    real(c_double), intent(in) :: value
    call rs_reserve(w, 8)
    w%d(w%n + 1:w%n + 8) = transfer(value, 0_c_int8_t, 8)
    w%n = w%n + 8
end subroutine

recursive subroutine rs_text(w, text)
    type(rs_writer), intent(inout) :: w
    character(len=*), intent(in) :: text
    call rs_u64(w, int(len(text), c_int64_t))
    if (len(text) == 0) return
    call rs_reserve(w, len(text))
    w%d(w%n + 1:w%n + len(text)) = transfer(text, 0_c_int8_t, len(text))
    w%n = w%n + len(text)
end subroutine

! A call with `count` arguments.
recursive subroutine rs_begin(w, count)
    type(rs_writer), intent(inout) :: w
    integer, intent(in) :: count
    w%n = 0
    call rs_reserve(w, 256)
    if (allocated(w%slots)) deallocate(w%slots)
    allocate(w%slots(0:max(count, 1) - 1))
    w%slots = 0
    call rs_u32(w, count)
end subroutine

recursive subroutine rs_put_nil(w)
    type(rs_writer), intent(inout) :: w
    call rs_u8(w, 0)
end subroutine

recursive subroutine rs_put_bool(w, value)
    type(rs_writer), intent(inout) :: w
    logical, intent(in) :: value
    call rs_u8(w, merge(1, 19, value))
end subroutine

recursive subroutine rs_put_int64(w, value)
    type(rs_writer), intent(inout) :: w
    integer(c_int64_t), intent(in) :: value
    call rs_u8(w, 2)
    call rs_u64(w, value)
end subroutine

recursive subroutine rs_put_int32(w, value)
    type(rs_writer), intent(inout) :: w
    integer, intent(in) :: value
    call rs_put_int64(w, int(value, c_int64_t))
end subroutine

recursive subroutine rs_put_real64(w, value)
    type(rs_writer), intent(inout) :: w
    real(c_double), intent(in) :: value
    call rs_u8(w, 4)
    call rs_f64(w, value)
end subroutine

recursive subroutine rs_put_real32(w, value)
    type(rs_writer), intent(inout) :: w
    real(c_float), intent(in) :: value
    call rs_put_real64(w, real(value, c_double))
end subroutine

recursive subroutine rs_put_complex64(w, value)
    type(rs_writer), intent(inout) :: w
    complex(c_double), intent(in) :: value
    call rs_u8(w, 18)
    call rs_f64(w, real(value, c_double))
    call rs_f64(w, aimag(value))
end subroutine

recursive subroutine rs_put_complex32(w, value)
    type(rs_writer), intent(inout) :: w
    complex(c_float), intent(in) :: value
    call rs_put_complex64(w, cmplx(value, kind=c_double))
end subroutine

recursive subroutine rs_put_string(w, value)
    type(rs_writer), intent(inout) :: w
    character(len=*), intent(in) :: value
    call rs_u8(w, 5)
    call rs_text(w, value)
end subroutine

! A list of `count` values (the values follow).
recursive subroutine rs_put_list(w, count)
    type(rs_writer), intent(inout) :: w
    integer, intent(in) :: count
    call rs_u8(w, 6)
    call rs_u64(w, int(count, c_int64_t))
end subroutine

! A map of `count` entries (keys and values follow, alternating).
recursive subroutine rs_put_map(w, count)
    type(rs_writer), intent(inout) :: w
    integer, intent(in) :: count
    call rs_u8(w, 9)
    call rs_u64(w, int(count, c_int64_t))
end subroutine

recursive subroutine rs_put_reals(w, values)
    type(rs_writer), intent(inout) :: w
    real(c_double), intent(in) :: values(:)
    call rs_u8(w, 7)
    call rs_u64(w, int(size(values), c_int64_t))
    if (size(values) == 0) return
    call rs_reserve(w, 8 * size(values))
    w%d(w%n + 1:w%n + 8 * size(values)) = transfer(values, 0_c_int8_t, 8 * size(values))
    w%n = w%n + 8 * size(values)
end subroutine

recursive subroutine rs_put_ints32(w, values)
    type(rs_writer), intent(inout) :: w
    integer, intent(in) :: values(:)
    integer :: i
    call rs_put_list(w, size(values))
    do i = 1, size(values)
        call rs_put_int64(w, int(values(i), c_int64_t))
    end do
end subroutine

recursive subroutine rs_put_ints64(w, values)
    type(rs_writer), intent(inout) :: w
    integer(c_int64_t), intent(in) :: values(:)
    integer :: i
    call rs_put_list(w, size(values))
    do i = 1, size(values)
        call rs_put_int64(w, values(i))
    end do
end subroutine

recursive subroutine rs_put_bools(w, values)
    type(rs_writer), intent(inout) :: w
    logical, intent(in) :: values(:)
    integer :: i
    call rs_put_list(w, size(values))
    do i = 1, size(values)
        call rs_put_bool(w, values(i))
    end do
end subroutine

! Fixed-length strings: trailing blanks are padding, not text.
recursive subroutine rs_put_chars(w, values)
    type(rs_writer), intent(inout) :: w
    character(len=*), intent(in) :: values(:)
    integer :: i
    call rs_put_list(w, size(values))
    do i = 1, size(values)
        call rs_put_string(w, trim(values(i)))
    end do
end subroutine

recursive subroutine rs_put_strings(w, values)
    type(rs_writer), intent(inout) :: w
    type(rosetta_string), intent(in) :: values(:)
    integer :: i
    call rs_put_list(w, size(values))
    do i = 1, size(values)
        if (allocated(values(i)%s)) then
            call rs_put_string(w, values(i)%s)
        else
            call rs_put_string(w, '')
        end if
    end do
end subroutine

! An object; `argument` is its position in the call (0 = first), or -1 inside a container.
recursive subroutine rs_put_object(w, o, argument)
    type(rs_writer), intent(inout) :: w
    class(rosetta_object), intent(in) :: o
    integer, intent(in) :: argument
    if (.not. rs_valid(o%rs_slot, o%rs_key)) then
        call rs_put_nil(w)
        return
    end if
    call rs_u8(w, 10)
    call rs_u64(w, rs_entries(o%rs_slot)%holder)
    call rs_u64(w, int(o%rs_slot, c_int64_t))
    if (argument >= 0 .and. argument < size(w%slots)) w%slots(argument) = o%rs_slot
end subroutine

! A Fortran procedure registered as entry `id`; the call holds it until it returns.
recursive subroutine rs_put_function(w, id)
    type(rs_writer), intent(inout) :: w
    integer, intent(in) :: id
    integer, allocatable :: grown(:)
    call rs_u8(w, 12)
    call rs_u64(w, int(id, c_int64_t))
    if (.not. allocated(w%callbacks)) allocate(w%callbacks(4))
    if (w%ncallbacks == size(w%callbacks)) then
        allocate(grown(2 * size(w%callbacks)))
        grown(1:w%ncallbacks) = w%callbacks(1:w%ncallbacks)
        call move_alloc(grown, w%callbacks)
    end if
    w%ncallbacks = w%ncallbacks + 1
    w%callbacks(w%ncallbacks) = id
end subroutine

! A reference argument: C++ writes its new value back to writeback `slot` (the value follows).
recursive subroutine rs_put_ref(w, slot)
    type(rs_writer), intent(inout) :: w
    integer, intent(in) :: slot
    call rs_u8(w, 13)
    call rs_u32(w, slot)
end subroutine

! A new entry for a Fortran procedure of callback signature `sig`.
recursive function rs_new_callback(sig) result(id)
    integer, intent(in) :: sig
    integer :: id
    id = rs_new_entry(0_c_int64_t, -1, 2)
    rs_entries(id)%sig = sig
end function

! ---------------------------------------------------------------- calls
recursive subroutine rs_ensure_init()
    if (rs_ready) return
    if (rs_c_init(1_c_int, c_funloc(rs_invoke_hook), c_funloc(rs_retain_hook)) /= 0) &
        error stop 'datamunge: the native library was generated by a different Rosetta version'
    rs_ready = .true.
end subroutine

! Copies `size` bytes of native memory.
recursive subroutine rs_copy_in(data, size, d)
    type(c_ptr), intent(in) :: data
    integer(c_size_t), intent(in) :: size
    integer(c_int8_t), allocatable, intent(out) :: d(:)
    integer(c_int8_t), pointer :: bytes(:)
    allocate(d(int(size)))
    if (size == 0 .or. .not. c_associated(data)) return
    call c_f_pointer(data, bytes, [size])
    d(:) = bytes(:)
end subroutine

recursive subroutine rs_call(index, w, r, in_function)
    integer, intent(in) :: index
    type(rs_writer), intent(inout) :: w
    type(rs_reader), intent(inout) :: r
    ! True from functions: Fortran output is then not flushed before the native call (see rs_in_function).
    logical, intent(in), optional :: in_function
    type(c_ptr) :: output
    integer(c_size_t) :: output_size
    integer(c_int) :: status
    integer :: i
    logical :: outer
    call rs_ensure_init()
    outer = rs_in_function
    if (present(in_function)) rs_in_function = rs_in_function .or. in_function
    if (.not. rs_in_function) flush(output_unit)
    rs_raised = .false.
    status = rs_c_call(int(index, c_int), w%d, int(w%n, c_size_t), output, output_size)
    rs_in_function = outer
    call rs_copy_in(output, output_size, r%d)
    if (c_associated(output)) call rs_c_free(output)
    r%at = 1
    call move_alloc(w%slots, r%slots)
    select case (status)
    case (0)
    case (1, 2)
        call rs_get_string(r, r%kind)
        call rs_get_string(r, r%message)
        r%failed = .true.
        r%code = int(status)
        if (status == 2) r%kind = 'fortran'
        do i = 1, len(r%kind)
            if (r%kind(i:i) == '-') r%kind(i:i) = '_'
        end do
    case default
        r%failed = .true.
        r%code = 3
        r%kind = 'allocation'
        r%message = 'out of memory in a native call'
    end select
    do i = 1, w%ncallbacks
        call rs_drop(w%callbacks(i))
    end do
    w%ncallbacks = 0
end subroutine

! Ends a call: sets `status`, or stops the program on an error without it.
recursive subroutine rs_end(r, status)
    type(rs_reader), intent(inout) :: r
    type(rosetta_error), intent(out), optional :: status
    if (present(status)) then
        status%code = r%code
        if (r%failed) then
            status%kind = r%kind
            status%message = r%message
        else
            status%kind = ''
            status%message = ''
        end if
    else if (r%failed) then
        error stop 'datamunge: ' // r%kind // ': ' // r%message
    end if
end subroutine

! ---------------------------------------------------------------- decoding
recursive subroutine rs_fail(r, message)
    type(rs_reader), intent(inout) :: r
    character(len=*), intent(in) :: message
    if (r%failed) return
    r%failed = .true.
    r%code = 1
    r%kind = 'binding'
    r%message = message
end subroutine

recursive logical function rs_need(r, n)
    type(rs_reader), intent(inout) :: r
    integer, intent(in) :: n
    rs_need = .false.
    if (r%failed) return
    if (.not. allocated(r%d)) then
        call rs_fail(r, 'malformed native value')
        return
    end if
    if (r%at + n - 1 > size(r%d)) then
        call rs_fail(r, 'malformed native value')
        return
    end if
    rs_need = .true.
end function

recursive integer function rs_get_u8(r)
    type(rs_reader), intent(inout) :: r
    rs_get_u8 = -1
    if (.not. rs_need(r, 1)) return
    rs_get_u8 = iand(int(r%d(r%at)), 255)
    r%at = r%at + 1
end function

recursive integer function rs_get_u32(r)
    type(rs_reader), intent(inout) :: r
    rs_get_u32 = 0
    if (.not. rs_need(r, 4)) return
    rs_get_u32 = int(transfer(r%d(r%at:r%at + 3), 0_c_int32_t))
    r%at = r%at + 4
end function

integer(c_int64_t) function rs_get_u64(r)
    type(rs_reader), intent(inout) :: r
    rs_get_u64 = 0
    if (.not. rs_need(r, 8)) return
    rs_get_u64 = transfer(r%d(r%at:r%at + 7), 0_c_int64_t)
    r%at = r%at + 8
end function

real(c_double) function rs_get_f64(r)
    type(rs_reader), intent(inout) :: r
    rs_get_f64 = 0
    if (.not. rs_need(r, 8)) return
    rs_get_f64 = transfer(r%d(r%at:r%at + 7), 0.0_c_double)
    r%at = r%at + 8
end function

! The length of a string, list or map, checked against the bytes left.
recursive integer function rs_get_length(r)
    type(rs_reader), intent(inout) :: r
    integer(c_int64_t) :: n
    rs_get_length = 0
    n = rs_get_u64(r)
    if (r%failed) return
    if (n < 0 .or. n > int(size(r%d) - r%at + 1, c_int64_t)) then
        call rs_fail(r, 'malformed native value')
        return
    end if
    rs_get_length = int(n)
end function

recursive subroutine rs_get_text(r, text)
    type(rs_reader), intent(inout) :: r
    character(len=:), allocatable, intent(inout) :: text
    integer :: n
    n = rs_get_length(r)
    if (r%failed) n = 0
    if (allocated(text)) deallocate(text)
    allocate(character(len=n) :: text)
    if (n == 0) return
    text = transfer(r%d(r%at:r%at + n - 1), text)
    r%at = r%at + n
end subroutine

! Skips a value of any type.
recursive subroutine rs_skip(r)
    type(rs_reader), intent(inout) :: r
    integer :: tag, n, i
    character(len=:), allocatable :: text
    integer(c_int64_t) :: ignored
    real(c_double) :: real_value
    tag = rs_get_u8(r)
    select case (tag)
    case (0, 1, 19)
    case (2, 12)
        ignored = rs_get_u64(r)
    case (4)
        real_value = rs_get_f64(r)
    case (18)
        real_value = rs_get_f64(r)
        real_value = rs_get_f64(r)
    case (3, 5, 14, 15)
        call rs_get_text(r, text)
    case (6, 16)
        n = rs_get_length(r)
        do i = 1, n
            call rs_skip(r)
        end do
    case (9)
        n = rs_get_length(r)
        do i = 1, 2 * n
            call rs_skip(r)
        end do
    case (8)
        call rs_skip(r)
        call rs_skip(r)
    case (7)
        n = rs_get_length(r)
        if (rs_need(r, 8 * n)) r%at = r%at + 8 * n
    case (10)
        ignored = rs_get_u64(r)
        i = rs_get_u32(r)
        ignored = rs_get_u64(r)
    case (11)
        ignored = rs_get_u64(r)
    case (17)
        i = rs_get_u32(r)
    case default
        call rs_fail(r, 'malformed native value')
    end select
end subroutine

! A value's type, for errors.
recursive function rs_tag_name(tag) result(name)
    integer, intent(in) :: tag
    character(len=:), allocatable :: name
    select case (tag)
    case (0)
        name = 'nothing'
    case (1, 19)
        name = 'a logical'
    case (2, 3)
        name = 'an integer'
    case (4)
        name = 'a real'
    case (18)
        name = 'a complex'
    case (5, 15)
        name = 'a string'
    case (14)
        name = 'an enumerator'
    case (6, 7, 16)
        name = 'a list'
    case (9)
        name = 'a map'
    case (8)
        name = 'a pair'
    case (10, 11, 17)
        name = 'an object'
    case (12)
        name = 'a function'
    case default
        name = 'a value'
    end select
end function

recursive subroutine rs_mismatch(r, tag, expected)
    type(rs_reader), intent(inout) :: r
    integer, intent(in) :: tag
    character(len=*), intent(in) :: expected
    if (r%failed) return
    call rs_fail(r, 'C++ returned ' // rs_tag_name(tag) // ' where Fortran expects ' // expected)
end subroutine

integer(c_int64_t) function rs_get_int64(r)
    type(rs_reader), intent(inout) :: r
    integer :: tag
    character(len=:), allocatable :: text
    rs_get_int64 = 0
    tag = rs_get_u8(r)
    select case (tag)
    case (2)
        rs_get_int64 = rs_get_u64(r)
    case (3)
        call rs_get_text(r, text)
        call rs_fail(r, 'integer result ' // text // ' is out of range for integer(c_int64_t)')
    case (0)
    case default
        call rs_mismatch(r, tag, 'an integer')
    end select
end function

recursive integer function rs_get_int(r)
    type(rs_reader), intent(inout) :: r
    integer(c_int64_t) :: value
    character(len=24) :: text
    rs_get_int = 0
    value = rs_get_int64(r)
    if (value > huge(0) .or. value < -huge(0) - 1) then
        write(text, '(i0)') value
        call rs_fail(r, 'integer result ' // trim(text) // ' is out of range for a default integer')
        return
    end if
    rs_get_int = int(value)
end function

real(c_double) function rs_get_real(r)
    type(rs_reader), intent(inout) :: r
    integer :: tag
    rs_get_real = 0
    tag = rs_get_u8(r)
    select case (tag)
    case (4)
        rs_get_real = rs_get_f64(r)
    case (2)
        rs_get_real = real(rs_get_u64(r), c_double)
    case (0)
    case default
        call rs_mismatch(r, tag, 'a real')
    end select
end function

real(c_float) function rs_get_real32(r)
    type(rs_reader), intent(inout) :: r
    rs_get_real32 = real(rs_get_real(r), c_float)
end function

recursive logical function rs_get_bool(r)
    type(rs_reader), intent(inout) :: r
    integer :: tag
    rs_get_bool = .false.
    tag = rs_get_u8(r)
    select case (tag)
    case (1)
        rs_get_bool = .true.
    case (0, 19)
    case default
        call rs_mismatch(r, tag, 'a logical')
    end select
end function

complex(c_double) function rs_get_complex(r)
    type(rs_reader), intent(inout) :: r
    integer :: tag
    real(c_double) :: re, im
    rs_get_complex = (0.0_c_double, 0.0_c_double)
    tag = rs_get_u8(r)
    select case (tag)
    case (18)
        re = rs_get_f64(r)
        im = rs_get_f64(r)
        rs_get_complex = cmplx(re, im, kind=c_double)
    case (4)
        rs_get_complex = cmplx(rs_get_f64(r), 0.0_c_double, kind=c_double)
    case (2)
        rs_get_complex = cmplx(real(rs_get_u64(r), c_double), 0.0_c_double, kind=c_double)
    case (0)
    case default
        call rs_mismatch(r, tag, 'a complex')
    end select
end function

complex(c_float) function rs_get_complex32(r)
    type(rs_reader), intent(inout) :: r
    rs_get_complex32 = cmplx(rs_get_complex(r), kind=c_float)
end function

recursive subroutine rs_get_string(r, text)
    type(rs_reader), intent(inout) :: r
    character(len=:), allocatable, intent(inout) :: text
    integer :: tag
    tag = rs_get_u8(r)
    select case (tag)
    case (5, 14, 15)
        call rs_get_text(r, text)
    case default
        if (tag /= 0) call rs_mismatch(r, tag, 'a string')
        if (allocated(text)) deallocate(text)
        allocate(character(len=0) :: text)
    end select
end subroutine

recursive function rs_get_char(r) result(c)
    type(rs_reader), intent(inout) :: r
    character(len=1) :: c
    character(len=:), allocatable :: text
    c = ' '
    call rs_get_string(r, text)
    if (len(text) > 0) c = text(1:1)
end function

! An enumerator: true and its label, or false and its value.
recursive logical function rs_get_enum(r, label, value)
    type(rs_reader), intent(inout) :: r
    character(len=:), allocatable, intent(out) :: label
    integer(c_int64_t), intent(out) :: value
    integer :: tag
    rs_get_enum = .false.
    value = 0
    label = ''
    tag = rs_get_u8(r)
    select case (tag)
    case (14, 5)
        call rs_get_text(r, label)
        rs_get_enum = .true.
    case (2)
        value = rs_get_u64(r)
    case (0)
    case default
        call rs_mismatch(r, tag, 'an enumerator')
    end select
end function

! The length of a list (or tuple); nothing is an empty list.
recursive integer function rs_get_count(r)
    type(rs_reader), intent(inout) :: r
    integer :: tag
    rs_get_count = 0
    tag = rs_get_u8(r)
    select case (tag)
    case (6, 16)
        rs_get_count = rs_get_length(r)
    case (0)
    case default
        call rs_mismatch(r, tag, 'a list')
    end select
end function

recursive integer function rs_get_map_count(r)
    type(rs_reader), intent(inout) :: r
    integer :: tag
    rs_get_map_count = 0
    tag = rs_get_u8(r)
    select case (tag)
    case (9)
        rs_get_map_count = rs_get_length(r)
    case (0)
    case default
        call rs_mismatch(r, tag, 'a map')
    end select
end function

! A pair or tuple of `n` values (the values follow).
recursive subroutine rs_get_tuple(r, n)
    type(rs_reader), intent(inout) :: r
    integer, intent(in) :: n
    integer :: tag, count
    tag = rs_get_u8(r)
    select case (tag)
    case (6, 16)
        count = rs_get_length(r)
        if (count /= n) call rs_fail(r, 'C++ returned a tuple of another size')
    case (8)
        if (n /= 2) call rs_fail(r, 'C++ returned a pair where Fortran expects a tuple')
    case default
        call rs_mismatch(r, tag, 'a tuple')
    end select
end subroutine

! Nothing (consumed) or a value (left to decode).
recursive logical function rs_take_nil(r)
    type(rs_reader), intent(inout) :: r
    rs_take_nil = .false.
    if (.not. rs_need(r, 1)) return
    if (r%d(r%at) == 0_c_int8_t) then
        r%at = r%at + 1
        rs_take_nil = .true.
    end if
end function

recursive subroutine rs_get_reals(r, values)
    type(rs_reader), intent(inout) :: r
    real(c_double), allocatable, intent(inout) :: values(:)
    integer :: tag, n, i
    if (allocated(values)) deallocate(values)
    tag = rs_get_u8(r)
    select case (tag)
    case (7)
        n = rs_get_length(r)
        if (r%failed .or. .not. rs_need(r, 8 * n)) n = 0
        allocate(values(n))
        if (n == 0) return
        values = transfer(r%d(r%at:r%at + 8 * n - 1), 0.0_c_double, n)
        r%at = r%at + 8 * n
    case (6, 16)
        n = rs_get_length(r)
        allocate(values(n))
        do i = 1, n
            values(i) = rs_get_real(r)
        end do
    case default
        if (tag /= 0) call rs_mismatch(r, tag, 'a list of reals')
        allocate(values(0))
    end select
end subroutine

recursive subroutine rs_get_reals32(r, values)
    type(rs_reader), intent(inout) :: r
    real(c_float), allocatable, intent(inout) :: values(:)
    real(c_double), allocatable :: wide(:)
    call rs_get_reals(r, wide)
    if (allocated(values)) deallocate(values)
    allocate(values(size(wide)))
    values = real(wide, c_float)
end subroutine

recursive subroutine rs_get_ints32(r, values)
    type(rs_reader), intent(inout) :: r
    integer, allocatable, intent(inout) :: values(:)
    integer :: n, i
    if (allocated(values)) deallocate(values)
    n = rs_get_count(r)
    allocate(values(n))
    do i = 1, n
        values(i) = rs_get_int(r)
    end do
end subroutine

recursive subroutine rs_get_ints64(r, values)
    type(rs_reader), intent(inout) :: r
    integer(c_int64_t), allocatable, intent(inout) :: values(:)
    integer :: n, i
    if (allocated(values)) deallocate(values)
    n = rs_get_count(r)
    allocate(values(n))
    do i = 1, n
        values(i) = rs_get_int64(r)
    end do
end subroutine

recursive subroutine rs_get_bools(r, values)
    type(rs_reader), intent(inout) :: r
    logical, allocatable, intent(inout) :: values(:)
    integer :: n, i
    if (allocated(values)) deallocate(values)
    n = rs_get_count(r)
    allocate(values(n))
    do i = 1, n
        values(i) = rs_get_bool(r)
    end do
end subroutine

recursive subroutine rs_get_strings(r, values)
    type(rs_reader), intent(inout) :: r
    type(rosetta_string), allocatable, intent(inout) :: values(:)
    integer :: n, i
    if (allocated(values)) deallocate(values)
    n = rs_get_count(r)
    allocate(values(n))
    do i = 1, n
        call rs_get_string(r, values(i)%s)
    end do
end subroutine

! Strings as a character array (as long as the longest; shorter ones padded with blanks).
recursive function rs_chars(values) result(chars)
    type(rosetta_string), intent(in) :: values(:)
    character(len=:), allocatable :: chars(:)
    integer :: i, longest
    longest = 0
    do i = 1, size(values)
        if (allocated(values(i)%s)) longest = max(longest, len(values(i)%s))
    end do
    allocate(character(len=longest) :: chars(size(values)))
    do i = 1, size(values)
        chars(i) = ''
        if (allocated(values(i)%s)) chars(i) = values(i)%s
    end do
end function

! An object (a new reference in `o`), or an unset object for nothing.
recursive subroutine rs_get_object(r, o)
    type(rs_reader), intent(inout) :: r
    class(rosetta_object), intent(inout) :: o
    integer :: tag, slot, klass, index
    integer(c_int64_t) :: holder, parent, id
    slot = 0
    tag = rs_get_u8(r)
    select case (tag)
    case (10)
        holder = rs_get_u64(r)
        klass = rs_get_u32(r)
        parent = rs_get_u64(r)
        if (r%failed) return
        slot = rs_new_entry(holder, klass, 1)
        if (parent >= 0 .and. allocated(r%slots)) then
            if (parent < size(r%slots)) then
                index = r%slots(int(parent))
                if (index > 0) then
                    rs_entries(slot)%parent = index
                    rs_entries(index)%count = rs_entries(index)%count + 1
                end if
            end if
        end if
    case (12)
        holder = rs_get_u64(r)
        if (r%failed) return
        slot = rs_new_entry(holder, -2, 1)
    case (11)
        id = rs_get_u64(r)
        if (r%failed) return
        slot = int(id)
        if (slot < 1 .or. slot > rs_used) then
            call rs_fail(r, 'invalid Fortran object reference')
            return
        end if
        if (rs_entries(slot)%kind /= 1) then
            call rs_fail(r, 'invalid Fortran object reference')
            return
        end if
        rs_entries(slot)%count = rs_entries(slot)%count + 1
    case (17)
        index = rs_get_u32(r)
        if (r%failed) return
        if (allocated(r%slots)) then
            if (index >= 0 .and. index < size(r%slots)) slot = r%slots(index)
        end if
        if (slot > 0) rs_entries(slot)%count = rs_entries(slot)%count + 1
    case (0)
    case default
        call rs_mismatch(r, tag, 'an object')
        return
    end select
    call rs_set(o, slot)
end subroutine

! The C++ object a director's constructor created, for the entry rs_attach made.
recursive subroutine rs_adopt(r, o)
    type(rs_reader), intent(inout) :: r
    class(rosetta_object), intent(inout) :: o
    integer :: tag, klass
    integer(c_int64_t) :: holder, parent
    if (r%failed) then
        call rs_set(o, 0)
        return
    end if
    tag = rs_get_u8(r)
    if (tag /= 10) then
        call rs_mismatch(r, tag, 'an object')
        call rs_set(o, 0)
        return
    end if
    holder = rs_get_u64(r)
    klass = rs_get_u32(r)
    parent = rs_get_u64(r)
    if (rs_valid(o%rs_slot, o%rs_key)) then
        rs_entries(o%rs_slot)%holder = holder
        rs_entries(o%rs_slot)%klass = klass
    end if
end subroutine

! ---------------------------------------------------------------- calls from C++
! kind 0 calls Fortran procedure `id`; kind 1 calls overridable method `generic` of director
! object `id`. The result (or an error message) goes into a buffer C++ frees.
recursive function rs_invoke_hook(kind, id, generic, data, size, result, result_size) bind(C) result(status)
    integer(c_int), value :: kind
    integer(c_int64_t), value :: id
    integer(c_int), value :: generic
    type(c_ptr), value :: data
    integer(c_size_t), value :: size
    type(c_ptr), intent(out) :: result
    integer(c_size_t), intent(out) :: result_size
    integer(c_int) :: status
    type(rs_reader) :: r
    type(rs_writer) :: w
    integer(c_int8_t), pointer :: bytes(:)
    integer :: count, slot, tag
    integer(c_int64_t) :: self
    rs_depth = rs_depth + 1
    status = 0
    call rs_copy_in(data, size, r%d)
    r%at = 1
    count = rs_get_u32(r)
    call rs_reserve(w, 64)
    rs_raised = .false.
    slot = int(id)
    if (slot < 1 .or. slot > rs_used) then
        call rs_fail(r, 'invalid Fortran reference')
    else if (kind == 0) then
        if (rs_entries(slot)%kind /= 2 .or. .not. associated(rs_callback_dispatch)) then
            call rs_fail(r, 'the Fortran procedure is no longer available')
        else
            call rs_callback_dispatch(rs_entries(slot)%sig, slot, r, w)
        end if
    else
        tag = rs_get_u8(r)
        self = rs_get_u64(r)
        if (tag /= 11 .or. int(self) /= slot .or. rs_entries(slot)%kind /= 1 .or. count < 1) then
            call rs_fail(r, 'invalid director call')
        else if (.not. associated(rs_entries(slot)%self) .or. .not. associated(rs_override_dispatch)) then
            call rs_fail(r, 'the Fortran object of a native reference is gone')
        else
            call rs_override_dispatch(int(generic), slot, r, w)
        end if
    end if
    if (rs_raised .or. r%failed) then
        w%n = 0
        if (rs_raised) then
            call rs_put_string(w, rs_raised_message)
            status = 2
        else
            call rs_put_string(w, r%message)
            status = 1
        end if
        rs_raised = .false.
    end if
    if (.not. rs_in_function) flush(output_unit)
    result_size = int(w%n, c_size_t)
    result = rs_c_alloc(int(max(w%n, 1), c_size_t))
    if (c_associated(result) .and. w%n > 0) then
        call c_f_pointer(result, bytes, [w%n])
        bytes(:) = w%d(1:w%n)
    end if
    rs_depth = rs_depth - 1
end function

! C++ took (delta 1) or dropped (delta -1) a reference to entry `id`.
recursive subroutine rs_retain_hook(id, delta) bind(C)
    integer(c_int64_t), value :: id
    integer(c_int), value :: delta
    integer :: slot
    slot = int(id)
    if (slot < 1 .or. slot > rs_used) return
    if (rs_entries(slot)%kind == 0) return
    rs_entries(slot)%retained = rs_entries(slot)%retained + int(delta)
    if (rs_entries(slot)%count <= 0 .and. rs_entries(slot)%retained <= 0) call rs_release_entry(slot)
end subroutine

! The director object of entry `id` (for the generated dispatcher).
recursive function rs_self(id) result(self)
    integer, intent(in) :: id
    class(rosetta_object), pointer :: self
    self => rs_entries(id)%self
end function
end module datamunge_rosetta

