    !> Sets C++ field `label`: Legend text (or the drawn text for Kind::Text); empty omits it.
    procedure :: set_label => dataseries_set_label
    !> Gets C++ field `color`: Layer color, including alpha (default RGBA{}, dark slate).
    procedure :: get_color => dataseries_get_color
    !> Sets C++ field `color`: Layer color, including alpha (default RGBA{}, dark slate).
    procedure :: set_color => dataseries_set_color
    !> Gets C++ field `stroke_width`: Line, Segment, and outline-Polygon width in pixels (default 2).
    procedure :: get_stroke_width => dataseries_get_stroke_width
    !> Sets C++ field `stroke_width`: Line, Segment, and outline-Polygon width in pixels (default 2).
    procedure :: set_stroke_width => dataseries_set_stroke_width
    !> Gets C++ field `marker_size`: Scatter marker radius, or Text font size, in pixels (default 4).
    procedure :: get_marker_size => dataseries_get_marker_size
    !> Sets C++ field `marker_size`: Scatter marker radius, or Text font size, in pixels (default 4).
    procedure :: set_marker_size => dataseries_set_marker_size
    !> Gets C++ field `bar_width`: Bar or Box width in data units (default 0.8).
