    !> Gets C++ field `vertical`: True for a vertical line at x = value (default false).
    procedure :: get_vertical => abline_get_vertical
    !> Sets C++ field `vertical`: True for a vertical line at x = value (default false).
    procedure :: set_vertical => abline_set_vertical
    !> Gets C++ field `value`: y-intercept for a sloped/horizontal line; x-position for a vertical line
    procedure :: get_value => abline_get_value
    !> Sets C++ field `value`: y-intercept for a sloped/horizontal line; x-position for a vertical line
    procedure :: set_value => abline_set_value
    !> Gets C++ field `slope`: Change in y per unit x; ignored when vertical (default 0).
    procedure :: get_slope => abline_get_slope
    !> Sets C++ field `slope`: Change in y per unit x; ignored when vertical (default 0).
    procedure :: set_slope => abline_set_slope
    !> Gets C++ field `color`: Line color (default opaque black).
    procedure :: get_color => abline_get_color
    !> Sets C++ field `color`: Line color (default opaque black).
    procedure :: set_color => abline_set_color
    !> Gets C++ field `stroke_width`: Line width in pixels (default 1).
    procedure :: get_stroke_width => abline_get_stroke_width
    !> Sets C++ field `stroke_width`: Line width in pixels (default 1).
    procedure :: set_stroke_width => abline_set_stroke_width
end type

