contains
    !> Gets C++ field `a`: Owned first input, unchanged by alignment.
    procedure :: get_a => dtwtrace_get_a
    !> Sets C++ field `a`: Owned first input, unchanged by alignment.
    procedure :: set_a => dtwtrace_set_a
    !> Gets C++ field `b`: Owned second input.
    procedure :: get_b => dtwtrace_get_b
    !> Sets C++ field `b`: Owned second input.
    procedure :: set_b => dtwtrace_set_b
    !> Gets C++ field `cumulative`: Actual positive-cell prefix costs, row-major.
    procedure :: get_cumulative => dtwtrace_get_cumulative
    !> Sets C++ field `cumulative`: Actual positive-cell prefix costs, row-major.
    procedure :: set_cumulative => dtwtrace_set_cumulative
    !> Gets C++ field `predecessors`: Actual selected directions, parallel to cumulative.
    procedure :: get_predecessors => dtwtrace_get_predecessors
    !> Sets C++ field `predecessors`: Actual selected directions, parallel to cumulative.
    procedure :: set_predecessors => dtwtrace_set_predecessors
    !> Gets C++ field `result`: Finite optimal distance and selected actual traceback.
    procedure :: get_result => dtwtrace_get_result
    !> Sets C++ field `result`: Finite optimal distance and selected actual traceback.
    procedure :: set_result => dtwtrace_set_result
    !> Gets C++ field `work`: Counts from the same recurrence/traceback.
    procedure :: get_work => dtwtrace_get_work
    !> Sets C++ field `work`: Counts from the same recurrence/traceback.
    procedure :: set_work => dtwtrace_set_work
    !> Gets C++ field `captured_entries`: Complete logical capture cost described above.
    procedure :: get_captured_entries => dtwtrace_get_captured_entries
    !> Sets C++ field `captured_entries`: Complete logical capture cost described above.
    procedure :: set_captured_entries => dtwtrace_set_captured_entries
end type

