!> report leave-one-out performance rather than a trivial resubstitution fit.
type, extends(rosetta_object), public :: KNNClassifier
contains
    !> C++ `datamunge::KNNClassifier::classes`.
    procedure :: classes => knnclassifier_classes
    !> C++ `datamunge::KNNClassifier::predictor_names`.
    procedure :: predictor_names => knnclassifier_predictor_names
    !> C++ `datamunge::KNNClassifier::observations`.
    procedure :: observations => knnclassifier_observations
    !> C++ `datamunge::KNNClassifier::k`.
    procedure :: k => knnclassifier_k
    !> C++ `datamunge::KNNClassifier::training_accuracy`.
    procedure :: training_accuracy => knnclassifier_training_accuracy
    !> "actual" column plus one numeric column per class (counts), both ordered as classes();
    !> leave-one-out.
    procedure :: confusion_matrix => knnclassifier_confusion_matrix
    !> C++ `datamunge::KNNClassifier::summary`.
    procedure :: summary => knnclassifier_summary
    !> C++ `datamunge::KNNClassifier::print_summary`.
    procedure :: print_summary => knnclassifier_print_summary
    !> C++ `datamunge::KNNClassifier::predict`.
    procedure :: predict => knnclassifier_predict
    !> "class" column plus one numeric vote-share column per class (votes_<class>).
    procedure :: predict_frame => knnclassifier_predict_frame
    !> Scatter of `data` in the (x_feature, y_feature) plane, colored by true class, with misclassified
    !> points overlaid in a distinct marker.
    procedure :: plot_classification => knnclassifier_plot_classification
    !> Background grid of predicted class regions plus training points; requires exactly 2 predictors.
    procedure :: plot_decision_regions_1 => knnclassifier_plot_decision_regions_1
    !> Background grid of predicted class regions plus training points; requires exactly 2 predictors.
    procedure :: plot_decision_regions_2 => knnclassifier_plot_decision_regions_2
    !> Background grid of predicted class regions plus training points; requires exactly 2 predictors.
    generic :: plot_decision_regions => plot_decision_regions_1, plot_decision_regions_2
end type

