! Starts a call (and installs this module's dispatchers in the runtime).
recursive subroutine rs_start(w, count)
    type(rs_writer), intent(inout) :: w
    integer, intent(in) :: count
    if (.not. associated(rs_class_name_fn)) then
        rs_callback_dispatch => rs_dispatch_callbacks
        rs_override_dispatch => rs_dispatch_overrides
        rs_class_name_fn => rs_class_names
    end if
    call rs_begin(w, count)
end subroutine

recursive function rs_enum1(r) result(value)
    type(rs_reader), intent(inout) :: r
    integer :: value
    character(len=:), allocatable :: label
    integer(c_int64_t) :: number
    if (rs_get_enum(r, label, number)) then
        select case (label)
        case ('Lex')
            value = MonomialOrder_Lex
        case ('Grlex')
            value = MonomialOrder_Grlex
        case ('Grevlex')
            value = MonomialOrder_Grevlex
        case default
            value = 0
            call rs_fail(r, 'unknown enumerator ' // label)
        end select
    else
        value = int(number)
    end if
end function

