    type(rs_reader), intent(inout) :: r
    integer :: value
    character(len=:), allocatable :: label
    integer(c_int64_t) :: number
    if (rs_get_enum(r, label, number)) then
        select case (label)
        case ('Square')
            value = StructuringElement_Square
        case ('Cross')
            value = StructuringElement_Cross
        case default
            value = 0
            call rs_fail(r, 'unknown enumerator ' // label)
        end select
    else
        value = int(number)
    end if
end function

