recursive function rs_enum5(r) result(value)
    type(rs_reader), intent(inout) :: r
    integer :: value
    character(len=:), allocatable :: label
    integer(c_int64_t) :: number
    if (rs_get_enum(r, label, number)) then
        select case (label)
        case ('origin')
            value = DTWPredecessor_origin
        case ('diagonal')
            value = DTWPredecessor_diagonal
