recursive function rs_cb1_add(f) result(id)
    procedure(fn_optional_tensorbspline_vector_real_vector_real) :: f
    integer :: id
    type(rs_cb1), allocatable :: grown(:)
    id = rs_new_callback(1)
    if (.not. allocated(rs_cb1s)) allocate(rs_cb1s(max(64, id)))
    if (id > size(rs_cb1s)) then
        allocate(grown(max(2 * size(rs_cb1s), id)))
        grown(1:size(rs_cb1s)) = rs_cb1s
        call move_alloc(grown, rs_cb1s)
    end if
    rs_cb1s(id)%p => f
end function

recursive subroutine rs_cb1_call(f, r, w)
    procedure(fn_optional_tensorbspline_vector_real_vector_real) :: f
    type(rs_reader), intent(inout) :: r
    type(rs_writer), intent(inout) :: w
    real(c_double), allocatable :: a1(:)
    real(c_double), allocatable :: a2(:)
    type(optional_tensorbspline) :: rs_res
    call rs_get_reals(r, a1)
    call rs_get_reals(r, a2)
    if (r%failed) return
    rs_res = f(a1, a2)
    if (rs_res%has_value) then
        call rs_put_object(w, rs_res%value, -1)
    else
        call rs_put_nil(w)
    end if
