recursive subroutine rs_dispatch_callbacks(which, id, r, w)
    integer, intent(in) :: which, id
    type(rs_reader), intent(inout) :: r
    type(rs_writer), intent(inout) :: w
    select case (which)
    case (1)
        call rs_cb1_call(rs_cb1s(id)%p, r, w)
    case default
        call rs_fail(r, 'unknown callback signature')
    end select
end subroutine

recursive subroutine rs_override_1(self, r, w)
    class(ArbitraryFunction) :: self
    type(rs_reader), intent(inout) :: r
    type(rs_writer), intent(inout) :: w
    type(rosetta_error) :: rs_st
    real(c_double), allocatable :: rs_a1(:)
