            call rosetta_raise(rs_st%message)
        else
            call rosetta_raise('error in a Fortran override')
        end if
        return
    end if
    if (.not. allocated(rs_res)) then
        call rs_put_list(w, 0)
    else
        call rs_put_list(w, size(rs_res))
        do rs_i1 = 1, size(rs_res)
            if (.not. allocated(rs_res(rs_i1)%v)) then
                call rs_put_list(w, 0)
            else
                call rs_put_reals(w, rs_res(rs_i1)%v)
            end if
        end do
    end if
end subroutine

