!> Creates a C++ `datamunge::algebra::MultivariatePolynomial`.
!>
!> @param num_variables Number of variables every exponent vector must have.
!> @param exponents One entry per term; each inner vector has length num_variables.
!> @param coefficients Parallel to exponents; terms with equal exponent vectors are summed, and any
!> resulting zero coefficient is dropped.
recursive function multivariatepolynomial_new_3(num_variables, exponents, coefficients, status) result(rs_res)
    integer, intent(in) :: num_variables
    type(vector_int), intent(in) :: exponents(:)
    real(c_double), intent(in) :: coefficients(:)
    type(rosetta_error), intent(out), optional :: status
    type(MultivariatePolynomial) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 4)
    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_put_int(rs_w, num_variables)
    call rs_put_list(rs_w, size(exponents))
    do rs_i1 = 1, size(exponents)
        if (.not. allocated(exponents(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_ints(rs_w, exponents(rs_i1)%v)
        end if
    end do
    call rs_put_reals(rs_w, coefficients)
    call rs_call(335, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

