!> Creates the C++ `datamunge::optim::ResidualFunction` of a Fortran extension.
!>
!> Creates the C++ object of `self`, an object of a Fortran type extending `ResidualFunction`: C++
!> calls of virtual methods then run the extension's overriding bindings. `self` must stay at its
!> address (a `target`, `save`d or allocated variable) while C++ uses it; the last copy of it going out
!> of scope (or `close`) releases the C++ object.
!>
!> @param self the Fortran object (it must have the `target` attribute)
recursive subroutine residualfunction_init_1(self, status)
    class(ResidualFunction), target, intent(inout) :: self
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_id
    rs_id = rs_attach(self)
    call rs_start(rs_w, 1)
    call rs_put_int(rs_w, int(rs_id, c_int64_t))
    call rs_call(379, rs_w, rs_r)
    call rs_adopt(rs_r, self)
    call rs_end(rs_r, status)
end subroutine

