!> Runs warmup (adapting the step size unless num_warmup is 0) then num_samples draws.
!>
!> @param log_posterior Log density (up to a constant) and its gradient.
!> @param initial_params Starting point on the unconstrained scale.
!> @return Draws, acceptance rate and final step size.
recursive function hmc_sample(self, log_posterior, initial_params, status) result(rs_res)
    class(HMC), intent(in) :: self
    class(DifferentiableFunction), intent(in) :: log_posterior
    real(c_double), intent(in) :: initial_params(:)
    type(rosetta_error), intent(out), optional :: status
    type(HMCResult) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, self, 0)
    call rs_put_object(rs_w, log_posterior, 1)
    call rs_put_reals(rs_w, initial_params)
    call rs_call(421, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

