    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_call(437, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> `log_target` need only be evaluable (optim::ArbitraryFunction), not differentiable.
!> `proposal_covariance` (a plain d x d nested vector, not linalg::DenseMatrix -- matrices never cross
!> the SWIG boundary as DenseMatrix anywhere in this library, only as nested vectors) must be symmetric
!> positive definite.
!>
!> @param log_target
!> @param proposal_mean
!> @param proposal_covariance
recursive function importancesampling_sample(self, log_target, proposal_mean, proposal_covariance, status)  &
    & result(rs_res)
    class(ImportanceSampling), intent(in) :: self
    class(ArbitraryFunction), intent(in) :: log_target
    real(c_double), intent(in) :: proposal_mean(:)
    type(vector_real), intent(in) :: proposal_covariance(:)
    type(rosetta_error), intent(out), optional :: status
    type(ImportanceSamplingResult) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 4)
    call rs_put_object(rs_w, self, 0)
    call rs_put_object(rs_w, log_target, 1)
    call rs_put_reals(rs_w, proposal_mean)
    call rs_put_list(rs_w, size(proposal_covariance))
    do rs_i1 = 1, size(proposal_covariance)
        if (.not. allocated(proposal_covariance(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, proposal_covariance(rs_i1)%v)
        end if
    end do
    call rs_call(438, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

