!> Maximizes `log_posterior` starting from `coordinates`, updating it in place to the mode found, and
!> returns the log-posterior density there.
!>
!> @param log_posterior
!> @param coordinates
recursive function map_optimize(self, log_posterior, coordinates, status) result(rs_res)
    class(MAP), intent(in) :: self
    class(DifferentiableFunction), intent(in) :: log_posterior
    real(c_double), allocatable, intent(inout) :: coordinates(:)
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_k
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, self, 0)
    call rs_put_object(rs_w, log_posterior, 1)
    call rs_put_ref(rs_w, 0)
    if (.not. allocated(coordinates)) then
        call rs_put_list(rs_w, 0)
    else
        call rs_put_reals(rs_w, coordinates)
    end if
    call rs_call(448, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    do rs_k = 1, rs_get_u32(rs_r)
        select case (rs_get_u32(rs_r))
        case (0)
            call rs_get_reals(rs_r, coordinates)
        case default
            call rs_skip(rs_r)
        end select
    end do
    call rs_end(rs_r, status)
end function

