!> Gets C++ field `samples`: Post-warmup draws, one vector<double> per sample.
recursive function rwmresult_get_samples(self, status) result(rs_res)
    class(RWMResult), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    type(vector_real), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(499, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_reals(rs_r, rs_res(rs_i1)%v)
    end do
    call rs_end(rs_r, status)
end function

!> Sets C++ field `samples`: Post-warmup draws, one vector<double> per sample.
!>
!> @param value the new value
recursive subroutine rwmresult_set_samples(self, value, status)
    class(RWMResult), intent(in) :: self
    type(vector_real), intent(in) :: value(:)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(value))
    do rs_i1 = 1, size(value)
        if (.not. allocated(value(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, value(rs_i1)%v)
        end if
    end do
    call rs_call(500, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

