!> Solves -k * Laplacian(u) = f with Dirichlet data u = dirichlet_values[i] at node dirichlet_nodes[i]
!> (every other node is a free unknown); k is the constant, isotropic diffusion coefficient. Throws
!> std::invalid_argument if dirichlet_nodes.size() != dirichlet_values.size(), if any index in
!> dirichlet_nodes is out of range, or if every node is constrained (nothing to solve for).
!>
!> @param mesh
!> @param k
!> @param f
!> @param dirichlet_nodes
!> @param dirichlet_values
recursive function fem2d_solve_1(mesh, k, f, dirichlet_nodes, dirichlet_values, status) result(rs_res)
    class(Mesh2D), intent(in) :: mesh
    real(c_double), intent(in) :: k
    class(ScalarField2D), intent(in) :: f
    integer, intent(in) :: dirichlet_nodes(:)
    real(c_double), intent(in) :: dirichlet_values(:)
    type(rosetta_error), intent(out), optional :: status
    type(FEM2DResult) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 5)
    call rs_put_object(rs_w, mesh, 0)
    call rs_put_real(rs_w, k)
    call rs_put_object(rs_w, f, 2)
    call rs_put_ints(rs_w, dirichlet_nodes)
    call rs_put_reals(rs_w, dirichlet_values)
    call rs_call(755, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Same as solve(), but f is one of a fixed set of named source terms instead of a live user-supplied
!> callback. source_params is interpreted positionally, with the listed defaults used for any parameter
!> past the end of source_params: - "zero":     f(x, y) = 0.                               
!> source_params unused. - "constant": f(x, y) = c.                                {c=1}. - "sine":    
!> f(x, y) = amplitude*sin(fx*x)*sin(fy*y).    {amplitude=1, fx=1, fy=1}.   Throws
!> std::invalid_argument for an unknown source name.
!>
!> @param mesh
!> @param k
!> @param source
!> @param source_params
!> @param dirichlet_nodes
!> @param dirichlet_values
recursive function fem2d_solve_builtin_1(mesh, k, source, source_params, dirichlet_nodes, dirichlet_values, status)  &
    & result(rs_res)
    class(Mesh2D), intent(in) :: mesh
    real(c_double), intent(in) :: k
    character(len=*), intent(in) :: source
    real(c_double), intent(in) :: source_params(:)
    integer, intent(in) :: dirichlet_nodes(:)
    real(c_double), intent(in) :: dirichlet_values(:)
    type(rosetta_error), intent(out), optional :: status
    type(FEM2DResult) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 6)
    call rs_put_object(rs_w, mesh, 0)
    call rs_put_real(rs_w, k)
    call rs_put_string(rs_w, source)
    call rs_put_reals(rs_w, source_params)
    call rs_put_ints(rs_w, dirichlet_nodes)
    call rs_put_reals(rs_w, dirichlet_values)
    call rs_call(756, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

