!> The time-update (prediction) step: x = F x, P = F P F^T + Q.
recursive subroutine kalmanfilter_predict(self, status)
    class(KalmanFilter), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
