    call rs_put_object(rs_w, self, 0)
    call rs_call(798, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> The measurement-update (correction) step given observation `z`: the standard innovation-covariance /
!> Kalman-gain form (S = H P H^T + R, K = P H^T S^-1, x += K(z - Hx), P = (I - KH) P) -- not the
!> numerically-hardened Joseph form, matching this codebase's general preference for the textbook
!> formula over a more robust but more complex alternative.
!>
!> @param z
recursive subroutine kalmanfilter_update(self, z, status)
    class(KalmanFilter), intent(in) :: self
    real(c_double), intent(in) :: z(:)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_reals(rs_w, z)
    call rs_call(799, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

