!> Runs predict() then update(z) for every z in `measurements`, in order, mutating this filter's
!> running state -- the ordinary causal (online) filtered estimate at every timestep.
!>
!> @param measurements
recursive function kalmanfilter_filter(self, measurements, status) result(rs_res)
    class(KalmanFilter), intent(in) :: self
    type(vector_real), intent(in) :: measurements(:)
    type(rosetta_error), intent(out), optional :: status
    type(KalmanState), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(measurements))
    do rs_i1 = 1, size(measurements)
        if (.not. allocated(measurements(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, measurements(rs_i1)%v)
        end if
    end do
    call rs_call(802, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> filter() followed by an RTS (Rauch-Tung-Striebel) backward smoothing pass, which uses the ENTIRE
!> sequence (not just data up to each point) to refine every estimate -- always at least as accurate as
!> the filtered estimate, at the cost of needing the full sequence in advance (not usable online).
!> Leaves this filter's running (x, P) at its post-filter state, same as filter() would.
!>
!> @param measurements
recursive function kalmanfilter_smooth(self, measurements, status) result(rs_res)
    class(KalmanFilter), intent(in) :: self
    type(vector_real), intent(in) :: measurements(:)
