    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(measurements))
    do rs_i1 = 1, size(measurements)
        if (.not. allocated(measurements(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, measurements(rs_i1)%v)
        end if
    end do
    call rs_call(803, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

