!> Evaluates the function at `x`.
!>
!> Virtual in C++: a Fortran extension of `VectorFunction` may override binding `evaluate` (same dummy
!> names), also when C++ calls it.
!>
!> @param x
recursive function vectorfunction_evaluate(self, x, status) result(rs_res)
    class(VectorFunction) :: self
    real(c_double), intent(in) :: x(:)
    type(rosetta_error), intent(out), optional :: status
    real(c_double), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_reals(rs_w, x)
    call rs_call(805, rs_w, rs_r, .true.)
    call rs_get_reals(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Creates the C++ `datamunge::filter::VectorFunction` of a Fortran extension.
!>
!> Creates the C++ object of `self`, an object of a Fortran type extending `VectorFunction`: C++ calls
!> of virtual methods then run the extension's overriding bindings. `self` must stay at its address (a
!> `target`, `save`d or allocated variable) while C++ uses it; the last copy of it going out of scope
!> (or `close`) releases the C++ object.
!>
!> @param self the Fortran object (it must have the `target` attribute)
recursive subroutine vectorfunction_init_1(self, status)
    class(VectorFunction), target, intent(inout) :: self
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_id
    rs_id = rs_attach(self)
    call rs_start(rs_w, 1)
    call rs_put_int(rs_w, int(rs_id, c_int64_t))
    call rs_call(806, rs_w, rs_r)
    call rs_adopt(rs_r, self)
    call rs_end(rs_r, status)
end subroutine

!> Propagates every ensemble member through the nonlinear f, each perturbed by an independently-sampled
!> draw from N(0, Q).
recursive subroutine ensemblekalmanfilter_predict(self, status)
    class(EnsembleKalmanFilter), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(807, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> The stochastic EnKF update (Evensen/Burgers): estimates the state-observation cross-covariance and
!> innovation covariance from the ensemble's own sample statistics, then updates each member with an
!> INDEPENDENTLY perturbed copy of `z` (adding a fresh N(0, R) draw to each member's correction) --
!> perturbing the observation per member, rather than applying one shared correction to all of them, is
!> what keeps the ensemble's spread statistically consistent after the update instead of collapsing it.
!>
!> @param z
recursive subroutine ensemblekalmanfilter_update(self, z, status)
    class(EnsembleKalmanFilter), intent(in) :: self
    real(c_double), intent(in) :: z(:)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_reals(rs_w, z)
    call rs_call(808, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

