!> Applies the callback to a single value.
!>
!> Virtual in C++: a Fortran extension of `Callback` may override binding `call` (same dummy names),
!> also when C++ calls it.
!>
!> @param x Input value.
!> @return Transformed value; the default implementation returns `x` unchanged.
recursive function callback_call(self, x, status) result(rs_res)
    class(Callback) :: self
    real(c_double), intent(in) :: x
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_real(rs_w, x)
    call rs_call(911, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    call rs_end(rs_r, status)
end function

