!> Implicitly parse a color name, #RRGGBB or #RRGGBBAA string. Names and hexadecimal digits are
!> case-insensitive. Hex alpha is the final byte divided by 255; omitted alpha is 1. Whitespace is not
!> stripped. Named green is (0, 128, 0); transparent is black with alpha zero. The input is copied
!> while parsing and is never borrowed by a plot or palette.
!>
!> **Example**
!>
!> ```
!> const dm::RGBA glass = std::string("#ff44ff55");
!> const auto plt = dm::plot(dm::c(0, 1), dm::c(1, 2), "data", "#ff44ff55");
!> std::print("{} {}\n", glass.r, dm::round(glass.alpha, 3)); // 255 0.333
!> ```
!>
!> @param color Color text; supported names are listed in the class description.
!> @throws std::invalid_argument For empty text, unknown names or malformed hex.
recursive function rgb_new_6(color, status) result(rs_res)
    character(len=*), intent(in) :: color
    type(rosetta_error), intent(out), optional :: status
    type(RGB) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_put_string(rs_w, color)
    call rs_call(921, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

