!> @param median Median line.
!> @param q3 Upper box edge (third quartile).
!> @param whisker_hi Upper whisker end.
!> @return This plot, for chaining.
recursive function rplot_box_1(self, position, whisker_lo, q1, median, q3, whisker_hi, status) result(rs_res)
    class(RPlot), intent(in) :: self
    real(c_double), intent(in) :: position
    real(c_double), intent(in) :: whisker_lo
    real(c_double), intent(in) :: q1
    real(c_double), intent(in) :: median
    real(c_double), intent(in) :: q3
    real(c_double), intent(in) :: whisker_hi
    type(rosetta_error), intent(out), optional :: status
    type(RPlot) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 7)
    call rs_put_object(rs_w, self, 0)
    call rs_put_real(rs_w, position)
    call rs_put_real(rs_w, whisker_lo)
    call rs_put_real(rs_w, q1)
    call rs_put_real(rs_w, median)
    call rs_put_real(rs_w, q3)
    call rs_put_real(rs_w, whisker_hi)
    call rs_call(1060, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

