    type(RPlot) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 5)
    call rs_put_object(rs_w, self, 0)
    call rs_put_reals(rs_w, x0)
    call rs_put_reals(rs_w, y0)
    call rs_put_reals(rs_w, x1)
    call rs_put_reals(rs_w, y1)
    call rs_call(1069, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

