!> Draws one straight segment from (x0[i], y0[i]) to (x1[i], y1[i]) for each i, like R's `segments(x0,
!> y0, x1, y1)`.
!>
!> All segments share `color` and `stroke_width` and form one Segment layer; their end
!> points count toward the axis ranges. Useful for error bars, residual sticks, and
!> dendrograms.
!>
!> **Example**
!>
!> ```
!> const auto x = dm::c(1.0, 2.0, 3.0);
!> const auto y = dm::c(2.0, 3.5, 3.0);
!> auto plt = dm::Plot(x, y).segments(x, y - 0.5, x, y + 0.5);  // +/- 0.5 error bars
!> std::print("{}\n", plt.series()[1].x.size());  // 6 (start, end, start, end, ...)
!> ```
!>
!> **References**
!>
!> - R `segments()`: https://stat.ethz.ch/R-manual/R-devel/library/graphics/html/segments.html
!>
!> See also: `abline()`, `polygon()`.
!>
!> @param x0 Start x coordinates.
!> @param y0 Start y coordinates.
!> @param x1 End x coordinates.
!> @param y1 End y coordinates.
!> @param color Segment color (default opaque black).
!> @param stroke_width Segment width in pixels (default 1).
!> @return This plot, for chaining.
!> @throws std::invalid_argument If the four vectors differ in length or are empty.
recursive function rplot_segments_3(self, x0, y0, x1, y1, color, stroke_width, status) result(rs_res)
    class(RPlot), intent(in) :: self
    real(c_double), intent(in) :: x0(:)
    real(c_double), intent(in) :: y0(:)
    real(c_double), intent(in) :: x1(:)
    real(c_double), intent(in) :: y1(:)
    class(RGB), intent(in) :: color
    real(c_double), intent(in) :: stroke_width
    type(rosetta_error), intent(out), optional :: status
    type(RPlot) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 7)
    call rs_put_object(rs_w, self, 0)
    call rs_put_reals(rs_w, x0)
    call rs_put_reals(rs_w, y0)
    call rs_put_reals(rs_w, x1)
    call rs_put_reals(rs_w, y1)
    call rs_put_object(rs_w, color, 5)
    call rs_put_real(rs_w, stroke_width)
    call rs_call(1069, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

