    do rs_i1 = 1, size(groups)
        if (.not. allocated(groups(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, groups(rs_i1)%v)
        end if
    end do
    call rs_put_chars(rs_w, names)
