    call rs_put_object(rs_w, self, 0)
    call rs_put_int(rs_w, width)
    call rs_put_int(rs_w, height)
    call rs_call(1073, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

