    call rs_call(1081, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Renders the multi-panel figure as a standalone SVG document and returns it as a string.
!>
!> Each panel becomes a nested `<svg>` scaled into its cell. A layout with no panels renders
!> as an empty white figure. The layout is not modified.
!>
!> **Example**
!>
!> ```
!> auto fig = dm::graphics::RLayout::create(2, 1).add(dm::Plot(dm::c(1.0, 2.0), dm::c(1.0, 2.0)));
!> std::print("{}\n", fig.to_svg().starts_with("<?xml"));  // true
!> ```
!>
!> See also: `save()`.
!>
!> @return The complete SVG text.
recursive function rlayout_to_svg(self, status) result(rs_res)
    class(RLayout), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    character(len=:), allocatable :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(1082, rs_w, rs_r, .true.)
    call rs_get_string(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Saves the figure, choosing the format from the extension: `.svg` (or none) writes SVG, `.png` /
!> `.pdf` write the same tiled raster the X11 viewer shows.
!>
!> The extension is case-sensitive and an existing file is overwritten. Raster panels are
!> re-rendered from the stored copies and scaled into their cells.
!>
!> **Example**
!>
!> See RLayout.
!>
!> See also: `save_svg()`, `to_svg()`, `show()`.
!>
!> @param path Destination file.
!> @throws std::invalid_argument For any other extension.
!> @throws std::runtime_error If the file cannot be written.
recursive subroutine rlayout_save(self, path, status)
    class(RLayout), intent(in) :: self
    character(len=*), intent(in) :: path
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_string(rs_w, path)
    call rs_call(1083, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> Writes to_svg() to `path` regardless of its extension.
