!> The `k` closest points to `query`, nearest first. Returns fewer than `k` points if the tree itself
!> has fewer than `k`.
!>
!> @param query
!> @param k
recursive function kdtree2d_k_nearest(self, query, k, status) result(rs_res)
    class(KDTree2D), intent(in) :: self
    class(Point2D), intent(in) :: query
    integer, intent(in) :: k
    type(rosetta_error), intent(out), optional :: status
    type(Point2D), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
