!> Gets C++ field `vertices`: The circumcenter of each Delaunay triangle -- the Voronoi diagram's
!> vertices (may repeat a coordinate if it's shared by multiple cells; kept as plain resolved points
!> rather than a shared, index-referenced pool for a simpler, binding-friendly shape).
recursive function voronoidiagram_get_vertices(self, status) result(rs_res)
    class(VoronoiDiagram), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    type(Point2D), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(1156, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> Sets C++ field `vertices`: The circumcenter of each Delaunay triangle -- the Voronoi diagram's
!> vertices (may repeat a coordinate if it's shared by multiple cells; kept as plain resolved points
!> rather than a shared, index-referenced pool for a simpler, binding-friendly shape).
!>
!> @param value the new value
recursive subroutine voronoidiagram_set_vertices(self, value, status)
    class(VoronoiDiagram), intent(in) :: self
