        call rs_put_object(rs_w, value(rs_i1), -1)
    end do
    call rs_call(1157, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> Gets C++ field `cells`: cells[i] is points[i]'s Voronoi cell boundary, as circumcenters in angular
!> order around points[i]. For an INTERIOR point this is a closed polygon (as with any polygon in this
!> module, the closing edge back to cells[i].front() is implicit). For a point on the convex hull, the
!> true Voronoi cell is unbounded -- this only returns its FINITE portion (an open polyline, missing
!> the two rays to infinity), since robustly constructing those rays is out of scope here. Empty for a
!> point that ended up in no Delaunay triangle (possible for an exactly-duplicated input point).
recursive function voronoidiagram_get_cells(self, status) result(rs_res)
    class(VoronoiDiagram), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    type(vector_point2d), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    integer :: rs_i2, rs_n2
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(1158, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        rs_n2 = rs_get_count(rs_r)
        if (allocated(rs_res(rs_i1)%v)) deallocate(rs_res(rs_i1)%v)
        allocate(rs_res(rs_i1)%v(rs_n2))
        do rs_i2 = 1, rs_n2
            call rs_get_object(rs_r, rs_res(rs_i1)%v(rs_i2))
        end do
    end do
    call rs_end(rs_r, status)
end function

!> Sets C++ field `cells`: cells[i] is points[i]'s Voronoi cell boundary, as circumcenters in angular
!> order around points[i]. For an INTERIOR point this is a closed polygon (as with any polygon in this
!> module, the closing edge back to cells[i].front() is implicit). For a point on the convex hull, the
!> true Voronoi cell is unbounded -- this only returns its FINITE portion (an open polyline, missing
!> the two rays to infinity), since robustly constructing those rays is out of scope here. Empty for a
!> point that ended up in no Delaunay triangle (possible for an exactly-duplicated input point).
!>
!> @param value the new value
recursive subroutine voronoidiagram_set_cells(self, value, status)
    class(VoronoiDiagram), intent(in) :: self
    type(vector_point2d), intent(in) :: value(:)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    integer :: rs_i2
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(value))
    do rs_i1 = 1, size(value)
        if (.not. allocated(value(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_list(rs_w, size(value(rs_i1)%v))
            do rs_i2 = 1, size(value(rs_i1)%v)
                call rs_put_object(rs_w, value(rs_i1)%v(rs_i2), -1)
            end do
        end if
    end do
    call rs_call(1159, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

