!> Form a lazy matrix product, fusing preceding inverse actions into a solve. An expression solve(A) *
!> B * C evaluates B * C before one native solve.
!>
!> **Example**
!>
!> ```
!> dm::LinalgMatrix A({1, 2}, 1, 2), b({3, 4}, 2, 1);
!> std::print("{:.0f}\n", A.multiply(b).values()[0]); // 11
!> ```
!>
!> @param other Right operand, retained by shared ownership.
!> @return Deferred product or solve handle.
!> @throws std::invalid_argument If inner dimensions differ.
recursive function linalgmatrix_multiply(self, other, status) result(rs_res)
    class(LinalgMatrix), intent(in) :: self
    class(LinalgMatrix), intent(in) :: other
    type(rosetta_error), intent(out), optional :: status
    type(LinalgMatrix) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_object(rs_w, other, 1)
    call rs_call(1165, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

