!> **Example**
!>
!> ```
!> dm::LinalgMatrix A({2}, 1, 1);
!> std::print("{:.1f}\n", A.inverse_action().values()[0]); // 0.5
!> ```
!>
!> @return Deferred inverse-action handle.
!> @throws std::invalid_argument If this matrix is not square.
recursive function linalgmatrix_inverse_action(self, status) result(rs_res)
    class(LinalgMatrix), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    type(LinalgMatrix) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(1166, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Evaluate a square system with LU or a tall least-squares system with QR.
!>
!> **Example**
!>
!> ```
!> dm::LinalgMatrix A({1, 1, 1}, 3, 1), b({1, 2, 3}, 3, 1);
!> std::print("{:.0f}\n", A.solve(b).values()[0]); // 2
!> ```
!>
!> @param rhs_ Matrix of right-hand sides with rows() rows.
!> @return Owned dense solution snapshot.
!> @throws std::invalid_argument For incompatible/wide shapes or nonfinite solve inputs.
!> @throws std::runtime_error For singular or rank-deficient systems.
recursive function linalgmatrix_solve(self, rhs_, status) result(rs_res)
    class(LinalgMatrix), intent(in) :: self
    class(LinalgMatrix), intent(in) :: rhs_
    type(rosetta_error), intent(out), optional :: status
    type(LinalgMatrix) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_object(rs_w, rhs_, 1)
    call rs_call(1167, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Evaluate once into an owned snapshot with no deferred operands.
!>
!> **Example**
!>
!> ```
!> dm::LinalgMatrix A({1, 2}, 1, 2);
!> auto snapshot = A.transpose().eval();
!> std::print("{}\n", snapshot.rows()); // 2
!> ```
!>
