!> Fits the surrogate to the observations so far.
!>
!> Virtual in C++: a Fortran extension of `BayesianSurrogate` may override binding `fit` (same dummy
!> names), also when C++ calls it.
!>
!> @param points Evaluated points, one per observation.
!> @param values Objective values at `points`.
recursive subroutine bayesiansurrogate_fit(self, points, values, status)
    class(BayesianSurrogate) :: self
    type(vector_real), intent(in) :: points(:)
    real(c_double), intent(in) :: values(:)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        if (.not. allocated(points(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, points(rs_i1)%v)
        end if
    end do
    call rs_put_reals(rs_w, values)
    call rs_call(1301, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> Scores a candidate; larger means more worth evaluating.
!>
!> Virtual in C++: a Fortran extension of `BayesianSurrogate` may override binding `acquisition` (same
!> dummy names), also when C++ calls it.
!>
!> @param point Candidate point.
!> @param incumbent Smallest objective value observed so far.
!> @return The acquisition value.
recursive function bayesiansurrogate_acquisition(self, point, incumbent, status) result(rs_res)
    class(BayesianSurrogate) :: self
    real(c_double), intent(in) :: point(:)
    real(c_double), intent(in) :: incumbent
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, self, 0)
    call rs_put_reals(rs_w, point)
    call rs_put_real(rs_w, incumbent)
    call rs_call(1302, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    call rs_end(rs_r, status)
end function

!> Creates the C++ `datamunge::optim::BayesianSurrogate` of a Fortran extension.
!>
!> Creates the C++ object of `self`, an object of a Fortran type extending `BayesianSurrogate`: C++
!> calls of virtual methods then run the extension's overriding bindings. `self` must stay at its
!> address (a `target`, `save`d or allocated variable) while C++ uses it; the last copy of it going out
!> of scope (or `close`) releases the C++ object.
!>
!> @param self the Fortran object (it must have the `target` attribute)
recursive subroutine bayesiansurrogate_init_1(self, status)
    class(BayesianSurrogate), target, intent(inout) :: self
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_id
    rs_id = rs_attach(self)
    call rs_start(rs_w, 1)
    call rs_put_int(rs_w, int(rs_id, c_int64_t))
    call rs_call(1303, rs_w, rs_r)
    call rs_adopt(rs_r, self)
    call rs_end(rs_r, status)
end subroutine

