!> Runs the loop and records every evaluation.
!>
!> @param function Objective to minimise.
!> @param lower Lower corner of the box.
!> @param upper Upper corner of the box (each entry larger than in `lower`).
!> @param surrogate Surrogate refitted before every proposal.
!> @return The evaluations and the best point.
!> @throws std::invalid_argument If the bounds are empty, differ in length or are not increasing.
recursive function bayesianoptimization_run(self, function, lower, upper, surrogate, status) result(rs_res)
    class(BayesianOptimization), intent(in) :: self
    class(ArbitraryFunction), intent(in) :: function
    real(c_double), intent(in) :: lower(:)
    real(c_double), intent(in) :: upper(:)
    class(BayesianSurrogate), intent(in) :: surrogate
    type(rosetta_error), intent(out), optional :: status
    type(BayesianOptimizationResult) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 5)
    call rs_put_object(rs_w, self, 0)
    call rs_put_object(rs_w, function, 1)
    call rs_put_reals(rs_w, lower)
    call rs_put_reals(rs_w, upper)
    call rs_put_object(rs_w, surrogate, 4)
    call rs_call(1328, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Runs the loop and returns only the best value.
!>
!> @param function Objective to minimise.
!> @param coordinates Output: the best point (its length must equal the bounds').
!> @param lower Lower corner of the box.
!> @param upper Upper corner of the box.
!> @param surrogate Surrogate refitted before every proposal.
!> @return The smallest observed value.
!> @throws std::invalid_argument If the bounds do not match `coordinates` or are not increasing.
recursive function bayesianoptimization_optimize(self, function, coordinates, lower, upper, surrogate, status)  &
    & result(rs_res)
    class(BayesianOptimization), intent(in) :: self
    class(ArbitraryFunction), intent(in) :: function
    real(c_double), allocatable, intent(inout) :: coordinates(:)
    real(c_double), intent(in) :: lower(:)
    real(c_double), intent(in) :: upper(:)
    class(BayesianSurrogate), intent(in) :: surrogate
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_k
    call rs_start(rs_w, 6)
    call rs_put_object(rs_w, self, 0)
    call rs_put_object(rs_w, function, 1)
    call rs_put_ref(rs_w, 0)
    if (.not. allocated(coordinates)) then
        call rs_put_list(rs_w, 0)
    else
        call rs_put_reals(rs_w, coordinates)
    end if
    call rs_put_reals(rs_w, lower)
    call rs_put_reals(rs_w, upper)
    call rs_put_object(rs_w, surrogate, 5)
    call rs_call(1329, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    do rs_k = 1, rs_get_u32(rs_r)
        select case (rs_get_u32(rs_r))
        case (0)
            call rs_get_reals(rs_r, coordinates)
        case default
            call rs_skip(rs_r)
        end select
    end do
    call rs_end(rs_r, status)
end function

