!> Minimizes `function` within [`lower_bound`, `upper_bound`], updating `coordinates` in place to the
!> best point found, and returns its value. The initial `coordinates` (clamped into bounds) seed one
!> nest of the population.
!>
!> @param function
!> @param coordinates
!> @param lower_bound
!> @param upper_bound
recursive function cuckoosearch_optimize(self, function, coordinates, lower_bound, upper_bound, status) result(rs_res)
    class(CuckooSearch), intent(in) :: self
    class(ArbitraryFunction), intent(in) :: function
    real(c_double), allocatable, intent(inout) :: coordinates(:)
    real(c_double), intent(in) :: lower_bound(:)
    real(c_double), intent(in) :: upper_bound(:)
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_k
    call rs_start(rs_w, 5)
    call rs_put_object(rs_w, self, 0)
    call rs_put_object(rs_w, function, 1)
    call rs_put_ref(rs_w, 0)
    if (.not. allocated(coordinates)) then
        call rs_put_list(rs_w, 0)
    else
        call rs_put_reals(rs_w, coordinates)
    end if
    call rs_put_reals(rs_w, lower_bound)
    call rs_put_reals(rs_w, upper_bound)
    call rs_call(1409, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    do rs_k = 1, rs_get_u32(rs_r)
        select case (rs_get_u32(rs_r))
        case (0)
            call rs_get_reals(rs_r, coordinates)
        case default
            call rs_skip(rs_r)
        end select
    end do
    call rs_end(rs_r, status)
end function

