!> Run NelderMead from the supplied point using the configured finite budget. Local simplex reflection,
!> expansion, contraction and shrink search. Starts with per-coordinate displacements
!> initial_simplex_scale and stops when simplex diameter and value spread are small. Those conditions
!> do not prove stationarity or a global minimum. O(p^2) simplex storage.
!>
!> **Example**
!>
!> ```
!> dm::optim::QuadraticObjective f({2,8},{1,-2});
!> dm::optim::NelderMeadOptions controls;controls.max_iterations=5;
!> std::vector<double> x{0,0};
!> const auto value=dm::optim::NelderMead(controls).optimize(f,x);
!> std::print("{}\n",std::isfinite(value)); // true
!> ```
!>
!> See also: `trace_optimize()`, `NelderMeadOptions`.
!>
!> @param function Borrowed ArbitraryFunction with matching finite output shapes.
!> @param coordinates Owned-by-caller finite start; overwritten with the native returned point.
!> @return Objective at the native returned coordinates; not a stop-status code.
!> @throws std::invalid_argument NelderMead: initial_simplex_scale must be positive; NelderMead:
!> reflection must be positive; NelderMead: expansion must be greater than 1; NelderMead: contraction
!> must be in (0, 1); NelderMead: shrink must be in (0, 1); NelderMead: tolerance must be non-negative.
!> @throws std::exception Exceptions from supplied callbacks propagate. Raw solvers do not uniformly
!> reject nonfinite inputs.
recursive function neldermead_optimize(self, function, coordinates, status) result(rs_res)
    class(NelderMead), intent(in) :: self
    class(ArbitraryFunction), intent(in) :: function
    real(c_double), allocatable, intent(inout) :: coordinates(:)
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_k
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, self, 0)
    call rs_put_object(rs_w, function, 1)
    call rs_put_ref(rs_w, 0)
    if (.not. allocated(coordinates)) then
        call rs_put_list(rs_w, 0)
    else
        call rs_put_reals(rs_w, coordinates)
    end if
    call rs_call(1625, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    do rs_k = 1, rs_get_u32(rs_r)
        select case (rs_get_u32(rs_r))
        case (0)
            call rs_get_reals(rs_r, coordinates)
        case default
            call rs_skip(rs_r)
        end select
    end do
    call rs_end(rs_r, status)
end function

