!> Run RMSProp from the supplied point using the configured finite budget. Uses an exponential
!> squared-gradient average with decay_rate, dividing by sqrt(average)+epsilon. Tests the pre-update
!> gradient norm after updating. Fixed rates can oscillate. O(p) local state, reset on every call.
!>
!> **Example**
!>
!> ```
!> dm::optim::QuadraticObjective f({2,8},{1,-2});
!> dm::optim::RMSPropOptions controls;controls.max_iterations=5;
!> std::vector<double> x{0,0};
!> const auto value=dm::optim::RMSProp(controls).optimize(f,x);
!> std::print("{}\n",std::isfinite(value)); // true
!> ```
!>
!> See also: `trace_optimize()`, `RMSPropOptions`.
!>
!> @param function Borrowed DifferentiableFunction with matching finite output shapes.
!> @param coordinates Owned-by-caller finite start; overwritten with the native returned point.
!> @return Objective at the native returned coordinates; not a stop-status code.
!> @throws std::invalid_argument RMSProp: step_size must be positive; RMSProp: decay_rate must be in
!> [0, 1); RMSProp: epsilon must be positive; RMSProp: tolerance must be non-negative.
!> @throws std::exception Exceptions from supplied callbacks propagate. Raw solvers do not uniformly
!> reject nonfinite inputs.
recursive function rmsprop_optimize(self, function, coordinates, status) result(rs_res)
    class(RMSProp), intent(in) :: self
    class(DifferentiableFunction), intent(in) :: function
    real(c_double), allocatable, intent(inout) :: coordinates(:)
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_k
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, self, 0)
    call rs_put_object(rs_w, function, 1)
    call rs_put_ref(rs_w, 0)
    if (.not. allocated(coordinates)) then
        call rs_put_list(rs_w, 0)
    else
        call rs_put_reals(rs_w, coordinates)
    end if
    call rs_call(1751, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    do rs_k = 1, rs_get_u32(rs_r)
        select case (rs_get_u32(rs_r))
        case (0)
            call rs_get_reals(rs_r, coordinates)
        case default
            call rs_skip(rs_r)
        end select
    end do
    call rs_end(rs_r, status)
end function

!> Borrow this optimizer's stored configuration.
!>
!> @return Const option reference, valid during this object's lifetime; no mutation.
recursive function rmsprop_options(self, status) result(rs_res)
    class(RMSProp), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    type(RMSPropOptions) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(1752, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

