!> Fits the GP to the observations (refitting hyperparameters when configured).
!>
!> Virtual in C++: a Fortran extension of `RBFGaussianProcessSurrogate` may override binding `fit`
!> (same dummy names), also when C++ calls it.
!>
!> @param points Training points, all of one dimension.
!> @param values Objective values.
!> @throws std::invalid_argument If the data are empty, mismatched or of mixed dimension.
recursive subroutine rbfgaussianprocesssurrogate_fit(self, points, values, status)
    class(RBFGaussianProcessSurrogate) :: self
    type(vector_real), intent(in) :: points(:)
    real(c_double), intent(in) :: values(:)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        if (.not. allocated(points(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, points(rs_i1)%v)
        end if
    end do
    call rs_put_reals(rs_w, values)
    call rs_call(1783, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

