!> Bayesian information criterion.
!>
!> `-2\ell + k\log n`, with `k` as in aic() and `n` = n_used().
recursive function arima_bic(self, status) result(rs_res)
    class(ARIMA), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(1954, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    call rs_end(rs_r, status)
end function

!> One-step-ahead fitted values on the original scale, aligned to the input series (the first
!> `observations() - n_used()` entries -- the presample points conditioned on by CSS -- are copies of
!> the observed value, matching a residual of exactly zero there rather than an undefined value).
recursive function arima_fitted_values(self, status) result(rs_res)
    class(ARIMA), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    real(c_double), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(1955, rs_w, rs_r, .true.)
    call rs_get_reals(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> One-step-ahead residuals on the original scale (zero for the presample points).
recursive function arima_residuals(self, status) result(rs_res)
    class(ARIMA), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    real(c_double), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(1956, rs_w, rs_r, .true.)
    call rs_get_reals(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Point forecasts for the next `horizon` periods, on the original scale.
!>
!> @param horizon Number of steps ahead to forecast.
!> @return A vector of length `horizon` (empty when `horizon` is 0).
recursive function arima_forecast(self, horizon, status) result(rs_res)
    class(ARIMA), intent(in) :: self
    integer, intent(in) :: horizon
    type(rosetta_error), intent(out), optional :: status
    real(c_double), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_int(rs_w, horizon)
    call rs_call(1957, rs_w, rs_r, .true.)
    call rs_get_reals(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> AR coefficients of the stationary (differenced) model after multiplying the regular and seasonal
!> polynomials,
!>
!> `w_t=\sum_i a_i w_{t-i}+\varepsilon_t+\sum_j b_j\varepsilon_{t-j}`.
!>
!> `a_i`, `i=1,\dots,p+sP` (zeros where no lag enters).
!>
!> @return The
recursive function arima_expanded_ar_coefficients(self, status) result(rs_res)
    class(ARIMA), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    real(c_double), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(1958, rs_w, rs_r, .true.)
    call rs_get_reals(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> MA coefficients
!>
!> `b_j` of the stationary model, after multiplying the regular and
!> seasonal MA polynomials; for the airline model `(\theta,0,\dots,0,\Theta,\theta\Theta)`.
!>
!> `b_j`, `j=1,\dots,q+sQ`.
!>
!> @return The
recursive function arima_expanded_ma_coefficients(self, status) result(rs_res)
    class(ARIMA), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    real(c_double), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(1959, rs_w, rs_r, .true.)
    call rs_get_reals(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> The first `count`
!>
!> `\psi`-weights of the full model, differencing included:
!> `y_t=\sum_{j\ge0}\psi_j\varepsilon_{t-j}` formally, with `\psi_0=1`.
!>
!> The h-step forecast error is `\sum_{j<h}\psi_j\varepsilon_{t+h-j}`, so its variance is
!> `\sigma^2\sum_{j<h}\psi_j^2`; forecast_with_intervals() uses exactly these weights.
!>
!> `\psi_0,\dots,\psi_{count-1}`.
!>
!> @param count Number of weights.
recursive function arima_psi_weights(self, count, status) result(rs_res)
    class(ARIMA), intent(in) :: self
    integer, intent(in) :: count
    type(rosetta_error), intent(out), optional :: status
    real(c_double), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_int(rs_w, count)
    call rs_call(1960, rs_w, rs_r, .true.)
    call rs_get_reals(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Point forecasts and their standard errors (from the psi-weight / MA(infinity) expansion of the full,
!> non-stationary AR/MA representation of y), on the original scale.
!>
!> @param horizon Number of steps ahead to forecast.
!> @return A pair (point forecasts, standard errors), each of length `horizon`.
recursive function arima_forecast_with_intervals(self, horizon, status) result(rs_res)
    class(ARIMA), intent(in) :: self
    integer, intent(in) :: horizon
    type(rosetta_error), intent(out), optional :: status
    type(pair_vector_real_vector_real) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_int(rs_w, horizon)
    call rs_call(1961, rs_w, rs_r, .true.)
    call rs_get_tuple(rs_r, 2)
    call rs_get_reals(rs_r, rs_res%first)
    call rs_get_reals(rs_r, rs_res%second)
    call rs_end(rs_r, status)
end function

!> Fit the model to a series.
!>
!> Uses the C++ default for `options`.
!>
!> @param y The observed series, in time order.
!> @throws std::invalid_argument If a seasonal order is set while seasonal_period is zero, or if the
!> series is too short for the requested differencing or AR order.
recursive function arima_new_1(y, status) result(rs_res)
    real(c_double), intent(in) :: y(:)
    type(rosetta_error), intent(out), optional :: status
    type(ARIMA) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_put_reals(rs_w, y)
    call rs_call(1962, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Fit the model to a series.
!>
!> @param y The observed series, in time order.
!> @param options Model orders and optimizer settings.
!> @throws std::invalid_argument If a seasonal order is set while seasonal_period is zero, or if the
!> series is too short for the requested differencing or AR order.
recursive function arima_new_2(y, options, status) result(rs_res)
    real(c_double), intent(in) :: y(:)
    class(ARIMAOptions), intent(in) :: options
    type(rosetta_error), intent(out), optional :: status
    type(ARIMA) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 3)
    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_put_reals(rs_w, y)
    call rs_put_object(rs_w, options, 2)
    call rs_call(1962, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

