!> Writes the matrix to `path`, choosing the format from the extension.
!>
!> `.svg` or no extension writes to_svg(); `.png` and `.pdf` write the tiled raster the
!> viewer shows. Needs no display.
!>
!> **Example**
!>
!> ```
!> const auto pairs = dm::Splom(dm::datasets::iris()).group_by("Species");
!> pairs.save("iris_pairs.svg");
!> pairs.save("iris_pairs.png");
!> ```
!>
!> @param path Destination file; an existing file is overwritten.
!> @throws std::invalid_argument For any other extension.
!> @throws std::runtime_error If the file cannot be written.
recursive subroutine splom_save(self, path, status)
    class(Splom), intent(in) :: self
    character(len=*), intent(in) :: path
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_string(rs_w, path)
    call rs_call(2174, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

