!> Builds the matrix from a facade DataFrame (the overload SWIG bindings use).
!>
!> See also: `Splom(const dstruct::DataFrame&`, `const std::vector<std::string>&)`.
!>
!> Uses the C++ default for `columns`.
!>
!> @param data Source frame; its values are copied.
!> @throws std::invalid_argument For a missing column, or fewer than two variables.
recursive function splom_new_1(data, status) result(rs_res)
    class(DataFrame), intent(in) :: data
    type(rosetta_error), intent(out), optional :: status
    type(Splom) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_put_object(rs_w, data, 1)
    call rs_call(2177, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Builds the matrix from a facade DataFrame (the overload SWIG bindings use).
!>
!> See also: `Splom(const dstruct::DataFrame&`, `const std::vector<std::string>&)`.
!>
!> @param data Source frame; its values are copied.
!> @param columns Columns to include in order; empty selects every numeric column plus every string
!> column with at most graphics::Splom::max_default_levels distinct values.
!> @throws std::invalid_argument For a missing column, or fewer than two variables.
recursive function splom_new_2(data, columns, status) result(rs_res)
    class(DataFrame), intent(in) :: data
    character(len=*), intent(in) :: columns(:)
    type(rosetta_error), intent(out), optional :: status
    type(Splom) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 3)
    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_put_object(rs_w, data, 1)
    call rs_put_chars(rs_w, columns)
    call rs_call(2177, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

