    call rs_start(rs_w, 2)
    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_put_real(rs_w, value_)
    call rs_call(2902, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

