    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_reals(rs_w, coefficients)
    call rs_call(2973, rs_w, rs_r, .true.)
    call rs_get_reals(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

