!> The per-axis bases.
!>
!> @return Reference valid for the lifetime of this object.
recursive function tensorbspline_bases(self, status) result(rs_res)
    class(TensorBSpline), intent(in) :: self
    type(rosetta_error), intent(out), optional :: status
    type(BSplineBasis), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(2978, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

