!> Evaluates at many points.
!>
!> **Example**
!>
!> ```
!> dm::fda::TensorBSpline f(dm::fda::BSplineBasis::open_uniform(1, 2), {0.0, 1.0});
!> std::print("{}\n", f.evaluate_points({{0.0}, {0.5}})); // [0, 0.5]
!> ```
!>
!> @param points Points, each of length d.
!> @return One value per point, in input order.
!> @throws std::invalid_argument As for evaluate(const std::vector<double>&).
recursive function tensorbspline_evaluate_points(self, points, status) result(rs_res)
    class(TensorBSpline), intent(in) :: self
    type(vector_real), intent(in) :: points(:)
    type(rosetta_error), intent(out), optional :: status
    real(c_double), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        if (.not. allocated(points(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, points(rs_i1)%v)
        end if
    end do
    call rs_call(2987, rs_w, rs_r, .true.)
    call rs_get_reals(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

