    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(axes))
    do rs_i1 = 1, size(axes)
        if (.not. allocated(axes(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, axes(rs_i1)%v)
        end if
    end do
    call rs_call(2988, rs_w, rs_r, .true.)
    call rs_get_reals(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

