    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, self, 0)
    call rs_call(2989, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> One-dimensional spline curve on `basis`.
!>
!> **Example**
!>
!> ```
!> dm::fda::TensorBSpline f(dm::fda::BSplineBasis::open_uniform(1, 2), {1.0, 3.0});
!> std::print("{}\n", f.evaluate(0.5)); // 2
!> ```
!>
!> @param basis Basis for the single axis.
!> @param coefficients One coefficient per basis function.
!> @throws std::invalid_argument If the coefficient count differs from basis.basis_size().
recursive function tensorbspline_new_1(basis, coefficients, status) result(rs_res)
    class(BSplineBasis), intent(in) :: basis
    real(c_double), intent(in) :: coefficients(:)
    type(rosetta_error), intent(out), optional :: status
    type(TensorBSpline) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 3)
    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_put_object(rs_w, basis, 1)
    call rs_put_reals(rs_w, coefficients)
    call rs_call(2990, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Tensor-product spline over one basis per axis.
!>
!> **Example**
!>
!> ```
!> auto b = dm::fda::BSplineBasis::open_uniform(0, 2);  // piecewise constant
!> dm::fda::TensorBSpline f({b, b}, {1, 2, 3, 4});
!> std::print("{}\n", f.evaluate({0.75, 0.25}));        // 3
!> ```
!>
!> @param bases One basis per dimension (at least one).
!> @param coefficients Row-major net whose size is the product of the basis sizes.
!> @throws std::invalid_argument If `bases` is empty or the net size does not match.
recursive function tensorbspline_new_2(bases, coefficients, status) result(rs_res)
    class(BSplineBasis), intent(in) :: bases(:)
    real(c_double), intent(in) :: coefficients(:)
    type(rosetta_error), intent(out), optional :: status
    type(TensorBSpline) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 3)
    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_put_list(rs_w, size(bases))
    do rs_i1 = 1, size(bases)
        call rs_put_object(rs_w, bases(rs_i1), -1)
    end do
    call rs_put_reals(rs_w, coefficients)
    call rs_call(2990, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

