    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        rs_n2 = rs_get_count(rs_r)
        if (allocated(rs_res(rs_i1)%v)) deallocate(rs_res(rs_i1)%v)
        allocate(rs_res(rs_i1)%v(rs_n2))
        do rs_i2 = 1, rs_n2
            call rs_get_tuple(rs_r, 2)
            rs_res(rs_i1)%v(rs_i2)%first = rs_get_int(rs_r)
            rs_res(rs_i1)%v(rs_i2)%second = rs_get_real(rs_r)
        end do
    end do
    call rs_end(rs_r, status)
end function

!> Sets C++ field `cols`: cols[j]: (refined i, R(i, j)) for coarse index j.
!>
!> @param value the new value
recursive subroutine axisrefinement_set_cols(self, value, status)
    class(AxisRefinement), intent(in) :: self
    type(vector_pair_int_real), intent(in) :: value(:)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    integer :: rs_i2
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(value))
    do rs_i1 = 1, size(value)
        if (.not. allocated(value(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_list(rs_w, size(value(rs_i1)%v))
            do rs_i2 = 1, size(value(rs_i1)%v)
                call rs_put_list(rs_w, 2)
                call rs_put_int(rs_w, value(rs_i1)%v(rs_i2)%first)
                call rs_put_real(rs_w, value(rs_i1)%v(rs_i2)%second)
            end do
        end if
    end do
    call rs_call(3015, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

