!> **Example**
!>
!> ```
!> dm::fda::HierarchicalBSpline h({0.0}, {1.0});
!> auto b = dm::fda::BSplineBasis::open_uniform(0, 1);
!> h.refine_region({0.0}, {0.3}, 1, [&](auto&, auto&) { return dm::fda::TensorBSpline(b, {1.0}); });
!> std::print("{}\n", h.evaluate({0.1})); // 1
!> ```
!>
!> @param region_min Lower corner.
!> @param region_max Upper corner.
!> @param depth Deepest depth.
!> @param factory Patch callback; std::nullopt leaves a cell unchanged.
!> @throws std::invalid_argument On invalid bounds or a patch of the wrong dimension.
recursive subroutine hierarchicalbspline_refine_region_2(self, region_min, region_max, depth, factory, status)
    class(HierarchicalBSpline), intent(in) :: self
    real(c_double), intent(in) :: region_min(:)
    real(c_double), intent(in) :: region_max(:)
    integer, intent(in) :: depth
    procedure(fn_optional_tensorbspline_vector_real_vector_real) :: factory
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 5)
    call rs_put_object(rs_w, self, 0)
    call rs_put_reals(rs_w, region_min)
    call rs_put_reals(rs_w, region_max)
    call rs_put_int(rs_w, depth)
    call rs_put_function(rs_w, rs_cb1_add(factory))
    call rs_call(3032, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> Least-squares fits a new patch on `cell` so the whole hierarchy matches `values` at `points`.
!>
!> The patch explains only what is left after every other patch on the path (the
!> residual values - evaluate(points)), in the spirit of Forsey-Bartels editing, so pass
!> raw data values rather than residuals. Points are global coordinates inside the cell.
!>
!> **Example**
!>
!> ```
!> dm::fda::HierarchicalBSpline h({0.0}, {1.0});
!> auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
!> h.fit_cell(h.root(), {b}, {{0.0}, {1.0}}, {1.0, 3.0});
!> std::print("{}\n", h.evaluate({0.5})); // 2
!> ```
!>
!> Uses the C++ default for `options`.
!>
!> @param cell Cell id; must not already have a patch (clear_spline() first to refit).
!> @param bases Patch bases on [0, 1], one per dimension.
!> @param points Sample locations inside the cell.
!> @param values One raw data value per point.
!> @throws std::out_of_range For an invalid id.
!> @throws std::invalid_argument If the cell has a patch, inputs are empty/mismatched, or a point lies
!> outside the cell.
!> @throws std::runtime_error If the local normal equations are singular.
recursive subroutine hierarchicalbspline_fit_cell_1(self, cell, bases, points, values, status)
    class(HierarchicalBSpline), intent(in) :: self
    integer, intent(in) :: cell
    class(BSplineBasis), intent(in) :: bases(:)
    type(vector_real), intent(in) :: points(:)
    real(c_double), intent(in) :: values(:)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 5)
    call rs_put_object(rs_w, self, 0)
    call rs_put_int(rs_w, cell)
    call rs_put_list(rs_w, size(bases))
    do rs_i1 = 1, size(bases)
        call rs_put_object(rs_w, bases(rs_i1), -1)
    end do
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        if (.not. allocated(points(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, points(rs_i1)%v)
        end if
    end do
    call rs_put_reals(rs_w, values)
    call rs_call(3033, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> Least-squares fits a new patch on `cell` so the whole hierarchy matches `values` at `points`.
!>
!> The patch explains only what is left after every other patch on the path (the
!> residual values - evaluate(points)), in the spirit of Forsey-Bartels editing, so pass
!> raw data values rather than residuals. Points are global coordinates inside the cell.
!>
!> **Example**
!>
!> ```
!> dm::fda::HierarchicalBSpline h({0.0}, {1.0});
!> auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
!> h.fit_cell(h.root(), {b}, {{0.0}, {1.0}}, {1.0, 3.0});
!> std::print("{}\n", h.evaluate({0.5})); // 2
!> ```
!>
!> @param cell Cell id; must not already have a patch (clear_spline() first to refit).
!> @param bases Patch bases on [0, 1], one per dimension.
!> @param points Sample locations inside the cell.
!> @param values One raw data value per point.
!> @param options Solver settings.
!> @throws std::out_of_range For an invalid id.
!> @throws std::invalid_argument If the cell has a patch, inputs are empty/mismatched, or a point lies
!> outside the cell.
!> @throws std::runtime_error If the local normal equations are singular.
recursive subroutine hierarchicalbspline_fit_cell_2(self, cell, bases, points, values, options, status)
    class(HierarchicalBSpline), intent(in) :: self
    integer, intent(in) :: cell
    class(BSplineBasis), intent(in) :: bases(:)
    type(vector_real), intent(in) :: points(:)
    real(c_double), intent(in) :: values(:)
    class(SplineSolveOptions), intent(in) :: options
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 6)
    call rs_put_object(rs_w, self, 0)
    call rs_put_int(rs_w, cell)
    call rs_put_list(rs_w, size(bases))
    do rs_i1 = 1, size(bases)
        call rs_put_object(rs_w, bases(rs_i1), -1)
    end do
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        if (.not. allocated(points(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, points(rs_i1)%v)
        end if
    end do
    call rs_put_reals(rs_w, values)
    call rs_put_object(rs_w, options, 5)
    call rs_call(3033, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> Penalized (P-spline) variant of fit_cell() with per-axis `lambdas` and difference `order`; all-zero
!> lambdas give fit_cell().
!>
!> **Example**
!>
!> ```
!> dm::fda::HierarchicalBSpline h({0.0}, {1.0});
!> auto b = dm::fda::BSplineBasis::open_uniform(3, 10);
!> h.fit_cell_penalized(h.root(), {b}, {{0.0}, {1.0}}, {0.0, 2.0}, {1e3});
!> std::print("{:.3f}\n", h.evaluate({0.5})); // 1.000
!> ```
!>
!> Uses the C++ default for `order = 2`, `options`.
!>
!> @param cell Cell id without a patch.
!> @param bases Patch bases on [0, 1].
!> @param points Sample locations inside the cell.
!> @param values Raw data values.
!> @param lambdas Nonnegative per-axis weights.
!> @throws std::out_of_range For an invalid id.
!> @throws std::invalid_argument As for fit_cell() and fit_tensor_pspline().
!> @throws std::runtime_error If the penalized normal equations are singular.
recursive subroutine hierarchicalbspline_fit_cell_penalized_1(self, cell, bases, points, values, lambdas, status)
    class(HierarchicalBSpline), intent(in) :: self
    integer, intent(in) :: cell
    class(BSplineBasis), intent(in) :: bases(:)
    type(vector_real), intent(in) :: points(:)
    real(c_double), intent(in) :: values(:)
    real(c_double), intent(in) :: lambdas(:)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 6)
    call rs_put_object(rs_w, self, 0)
    call rs_put_int(rs_w, cell)
    call rs_put_list(rs_w, size(bases))
    do rs_i1 = 1, size(bases)
        call rs_put_object(rs_w, bases(rs_i1), -1)
    end do
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        if (.not. allocated(points(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, points(rs_i1)%v)
        end if
    end do
    call rs_put_reals(rs_w, values)
    call rs_put_reals(rs_w, lambdas)
    call rs_call(3034, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

