    call rs_put_object(rs_w, self, 0)
    call rs_put_int(rs_w, level)
    call rs_put_ints(rs_w, index)
    call rs_call(3055, rs_w, rs_r, .true.)
    rs_res = rs_get_bool(rs_r)
