end function

!> Every active multi-index at `level`, in row-major order.
!>
!> **Example**
!>
!> ```
!> auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
!> dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 1.0}));
!> std::print("{}\n", thb.active_indices(0).size()); // 2
!> ```
!>
!> @param level Level.
!> @return Multi-indices.
!> @throws std::out_of_range For an invalid level.
recursive function truncatedhierarchicalbspline_active_indices(self, level, status) result(rs_res)
    class(TruncatedHierarchicalBSpline), intent(in) :: self
    integer, intent(in) :: level
    type(rosetta_error), intent(out), optional :: status
    type(vector_int), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_int(rs_w, level)
    call rs_call(3056, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_ints(rs_r, rs_res(rs_i1)%v)
    end do
    call rs_end(rs_r, status)
end function

