!> thb.refine(thb.root(), 1);                      // adds a knot at 0.5
!> thb.fit({{0.0}, {0.25}, {0.5}, {0.75}, {1.0}}, {1.0, 0.5, 0.0, 0.5, 1.0}); // |2x - 1|
!> std::print("{:.3f}\n", thb.evaluate({0.75})); // 0.500
!> ```
!>
!> Uses the C++ default for `options`.
!>
!> @param points Sample locations inside the domain.
!> @param values One value per point.
!> @throws std::invalid_argument On empty/mismatched inputs or points outside the domain.
!> @throws std::runtime_error If some active function has too little data (singular).
recursive subroutine truncatedhierarchicalbspline_fit_1(self, points, values, status)
    class(TruncatedHierarchicalBSpline), intent(in) :: self
    type(vector_real), intent(in) :: points(:)
    real(c_double), intent(in) :: values(:)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
