    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        if (.not. allocated(points(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, points(rs_i1)%v)
        end if
    end do
    call rs_put_reals(rs_w, values)
    call rs_call(3063, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> Least-squares fit of every active coefficient on every level at once (replaces the current
!> function).
!>
!> **Example**
!>
!> ```
!> auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
!> dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 0.0}));
!> thb.refine(thb.root(), 1);                      // adds a knot at 0.5
!> thb.fit({{0.0}, {0.25}, {0.5}, {0.75}, {1.0}}, {1.0, 0.5, 0.0, 0.5, 1.0}); // |2x - 1|
!> std::print("{:.3f}\n", thb.evaluate({0.75})); // 0.500
!> ```
!>
!> @param points Sample locations inside the domain.
!> @param values One value per point.
!> @param options Solver settings.
!> @throws std::invalid_argument On empty/mismatched inputs or points outside the domain.
!> @throws std::runtime_error If some active function has too little data (singular).
recursive subroutine truncatedhierarchicalbspline_fit_2(self, points, values, options, status)
    class(TruncatedHierarchicalBSpline), intent(in) :: self
    type(vector_real), intent(in) :: points(:)
    real(c_double), intent(in) :: values(:)
    class(SplineSolveOptions), intent(in) :: options
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 4)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        if (.not. allocated(points(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, points(rs_i1)%v)
        end if
    end do
    call rs_put_reals(rs_w, values)
    call rs_put_object(rs_w, options, 3)
    call rs_call(3063, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> Penalized all-level fit: adds lambda_k times the squared order-q differences along axis k of every
!> run of q + 1 neighbouring active coefficients of a level.
!>
!> Differences that would involve an inactive coefficient are omitted, so for q >= 1
!> constant coefficients (and, generally, polynomials of degree < q in the coefficient
!> index on each level) are unpenalized; q = 0 is ridge regression on all coefficients.
!>
!> **Example**
!>
!> ```
!> auto b = dm::fda::BSplineBasis::open_uniform(2, 6);
!> dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, std::vector<double>(6, 0.0)));
!> thb.refine_region({0.0}, {0.5}, 1);
!> thb.fit_penalized({{0.0}, {1.0}}, {2.0, 2.0}, {1.0}, 1);
!> std::print("{:.3f}\n", thb.evaluate({0.3})); // 2.000
!> ```
!>
!> Uses the C++ default for `order = 2`, `options`.
!>
!> @param points Sample locations.
!> @param values One value per point.
!> @param lambdas Nonnegative per-axis weights.
!> @throws std::invalid_argument As for fit() and tensor_difference_penalty().
!> @throws std::runtime_error If the normal equations are singular.
recursive subroutine truncatedhierarchicalbspline_fit_penalized_1(self, points, values, lambdas, status)
    class(TruncatedHierarchicalBSpline), intent(in) :: self
    type(vector_real), intent(in) :: points(:)
    real(c_double), intent(in) :: values(:)
    real(c_double), intent(in) :: lambdas(:)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 4)
    call rs_put_object(rs_w, self, 0)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        if (.not. allocated(points(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, points(rs_i1)%v)
        end if
    end do
    call rs_put_reals(rs_w, values)
    call rs_put_reals(rs_w, lambdas)
    call rs_call(3064, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

