!> @param path
recursive function nntensor_load_npy_1(path, status) result(rs_res)
    character(len=*), intent(in) :: path
    type(rosetta_error), intent(out), optional :: status
    type(NnTensor) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_string(rs_w, path)
    call rs_call(3075, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> An empty (undefined) tensor.
recursive function nntensor_new_1(status) result(rs_res)
    type(rosetta_error), intent(out), optional :: status
    type(NnTensor) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_call(3123, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> `values` in row-major order filling `shape`; dtype "float32", "float64", "int32", "int64" or "bool".
!>
!> Uses the C++ default for `dtype = "float32"`.
!>
!> @param values
!> @param shape
recursive function nntensor_new_2(values, shape, status) result(rs_res)
    real(c_double), intent(in) :: values(:)
    integer, intent(in) :: shape(:)
    type(rosetta_error), intent(out), optional :: status
    type(NnTensor) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 3)
    call rs_put_int(rs_w, 0_c_int64_t)
    call rs_put_reals(rs_w, values)
    call rs_put_ints(rs_w, shape)
    call rs_call(3123, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> `values` in row-major order filling `shape`; dtype "float32", "float64", "int32", "int64" or "bool".
