!> Same computation as dijkstra(), but returned as (vertex, distance) pairs in vertices() order rather
!> than an unordered_map -- a binding-friendly shape (plain vector<pair<>>, using the same
!> std_pair/std_vector machinery already relied on elsewhere) for language bindings where
!> std::unordered_map isn't cleanly exposed.
!>
!> @param source
recursive function weightedgraph_dijkstra_distances(self, source, status) result(rs_res)
    class(WeightedGraph), intent(in) :: self
    character(len=*), intent(in) :: source
    type(rosetta_error), intent(out), optional :: status
    type(pair_string_real), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_string(rs_w, source)
    call rs_call(3226, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_tuple(rs_r, 2)
        call rs_get_string(rs_r, rs_res(rs_i1)%first)
        rs_res(rs_i1)%second = rs_get_real(rs_r)
    end do
    call rs_end(rs_r, status)
end function

!> Same computation as bellman_ford(), but returned as (vertex, distance) pairs in vertices() order
!> rather than an unordered_map -- see dijkstra_distances() for why. Empty (with has_negative_cycle()
!> separately reporting the reason) when a negative cycle makes the distances themselves meaningless.
!>
!> @param source
recursive function weightedgraph_bellman_ford_distances(self, source, status) result(rs_res)
    class(WeightedGraph), intent(in) :: self
    character(len=*), intent(in) :: source
    type(rosetta_error), intent(out), optional :: status
    type(pair_string_real), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, self, 0)
    call rs_put_string(rs_w, source)
    call rs_call(3227, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
