    class(Polynomial), intent(in) :: r
    class(Polynomial), intent(in) :: scale_reference
    type(rosetta_error), intent(out), optional :: status
    logical :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, r, 0)
    call rs_put_object(rs_w, scale_reference, 1)
    call rs_call(10, rs_w, rs_r, .true.)
    rs_res = rs_get_bool(rs_r)
    call rs_end(rs_r, status)
end function

