    call rs_put_object(rs_w, b, 1)
    call rs_call(13, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Builds the Sturm sequence of p: p0 = p, p1 = p', and p_(i+1) = -rem(p_(i-1), p_i) until reaching a
!> constant (or zero) polynomial. Used to count/isolate the real roots of p in an interval via sign
!> changes (Sturm's theorem). p should be square-free for the sign-change count to equal the number of
!> DISTINCT real roots exactly; callers with a polynomial that may have repeated roots should first run
!> square_free_factorization() and apply Sturm's theorem to each factor.
!>
!> @param p
recursive function sturm_sequence_1(p, status) result(rs_res)
    class(Polynomial), intent(in) :: p
    type(rosetta_error), intent(out), optional :: status
    type(Polynomial), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, p, 0)
    call rs_call(14, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

