    integer :: rs_i1
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, p, 0)
    call rs_put_list(rs_w, size(basis))
    do rs_i1 = 1, size(basis)
        call rs_put_object(rs_w, basis(rs_i1), -1)
    end do
    call rs_put_int(rs_w, order)
    call rs_call(36, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

