!> Buchberger's algorithm: computes a Groebner basis of the ideal generated by `generators` under
!> `order`. Basic textbook form (no Buchberger-criterion pair-skipping optimizations, matching this
!> module's "simple, correct" scoping elsewhere) -- reduces every S-polynomial against the CURRENT
!> basis and appends any nonzero remainder until no pair produces one.
!>
!> @param generators
!> @param order
recursive function groebner_basis_1(generators, order, status) result(rs_res)
    class(MultivariatePolynomial), intent(in) :: generators(:)
    integer, intent(in) :: order
    type(rosetta_error), intent(out), optional :: status
    type(MultivariatePolynomial), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 2)
    call rs_put_list(rs_w, size(generators))
    do rs_i1 = 1, size(generators)
        call rs_put_object(rs_w, generators(rs_i1), -1)
    end do
    call rs_put_int(rs_w, order)
    call rs_call(38, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

