!> Keeps only the response-field entries that are a strict local maximum within a (2*radius+1)^2 window
!> AND exceed `threshold`, as a sorted-by-descending-response Corner list -- the standard
!> non-max-suppression + thresholding pass shared by every response-map-based corner detector.
!>
!> @param response
!> @param width
!> @param height
!> @param threshold
!> @param nms_radius
recursive function extract_local_maxima_1(response, width, height, threshold, nms_radius, status) result(rs_res)
    real(c_double), intent(in) :: response(:)
    integer, intent(in) :: width
    integer, intent(in) :: height
    real(c_double), intent(in) :: threshold
    integer, intent(in) :: nms_radius
    type(rosetta_error), intent(out), optional :: status
    type(Corner), allocatable :: rs_res(:)
