!> The two points where the infinite line `line` crosses the border of a `image_width` x `image_height`
!> image, for drawing/visualization. Returns false (and leaves the output points unchanged) if the line
!> doesn't intersect the image rectangle at all (only possible for a line entirely outside it).
!>
!> @param line
!> @param image_width_
!> @param image_height_
!> @param p1
!> @param p2
recursive function line_endpoints_1(line, image_width_, image_height_, p1, p2, status) result(rs_res)
    class(HoughLine), intent(in) :: line
    integer, intent(in) :: image_width_
    integer, intent(in) :: image_height_
    type(pair_int_int), intent(inout) :: p1
    type(pair_int_int), intent(inout) :: p2
    type(rosetta_error), intent(out), optional :: status
    logical :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_k
    call rs_start(rs_w, 5)
    call rs_put_object(rs_w, line, 0)
    call rs_put_int(rs_w, image_width_)
    call rs_put_int(rs_w, image_height_)
    call rs_put_ref(rs_w, 0)
    call rs_put_list(rs_w, 2)
    call rs_put_int(rs_w, p1%first)
    call rs_put_int(rs_w, p1%second)
    call rs_put_ref(rs_w, 1)
    call rs_put_list(rs_w, 2)
    call rs_put_int(rs_w, p2%first)
    call rs_put_int(rs_w, p2%second)
    call rs_call(74, rs_w, rs_r, .true.)
    rs_res = rs_get_bool(rs_r)
    do rs_k = 1, rs_get_u32(rs_r)
        select case (rs_get_u32(rs_r))
        case (0)
            call rs_get_tuple(rs_r, 2)
            p1%first = rs_get_int(rs_r)
            p1%second = rs_get_int(rs_r)
        case (1)
            call rs_get_tuple(rs_r, 2)
            p2%first = rs_get_int(rs_r)
            p2%second = rs_get_int(rs_r)
        case default
            call rs_skip(rs_r)
        end select
    end do
    call rs_end(rs_r, status)
end function

!> Standard Hough line transform: every pixel of `img` whose grayscale luma is >= `edge_threshold`
!> votes, in a rho-theta accumulator (theta stepped every degree over [0, pi), rho stepped every pixel
!> over the image's diagonal range), for every line that could pass through it. Returns every
!> accumulator cell with at least `min_votes`, non-max-suppressed within a (2*nms_radius+1) rho-theta
!> cell window so a single real line doesn't produce a cluster of near-duplicate near-identical
!> results. Intended input is an edge map (e.g. image::sobel_edges()'s output), not a raw photo.
!>
!> Uses the C++ default for `edge_threshold = 128`, `min_votes = 50`, `nms_radius = 5`.
!>
!> @param img
recursive function hough_lines_1(img, status) result(rs_res)
    class(Image), intent(in) :: img
    type(rosetta_error), intent(out), optional :: status
    type(HoughLine), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, img, 0)
    call rs_call(75, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

