    end do
    call rs_end(rs_r, status)
end function

!> Standard Hough line transform: every pixel of `img` whose grayscale luma is >= `edge_threshold`
!> votes, in a rho-theta accumulator (theta stepped every degree over [0, pi), rho stepped every pixel
!> over the image's diagonal range), for every line that could pass through it. Returns every
!> accumulator cell with at least `min_votes`, non-max-suppressed within a (2*nms_radius+1) rho-theta
!> cell window so a single real line doesn't produce a cluster of near-duplicate near-identical
!> results. Intended input is an edge map (e.g. image::sobel_edges()'s output), not a raw photo.
!>
!> @param img
!> @param edge_threshold
!> @param min_votes
!> @param nms_radius
recursive function hough_lines_4(img, edge_threshold, min_votes, nms_radius, status) result(rs_res)
    class(Image), intent(in) :: img
    integer, intent(in) :: edge_threshold
    integer, intent(in) :: min_votes
    integer, intent(in) :: nms_radius
    type(rosetta_error), intent(out), optional :: status
    type(HoughLine), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 4)
    call rs_put_object(rs_w, img, 0)
    call rs_put_int(rs_w, edge_threshold)
    call rs_put_int(rs_w, min_votes)
    call rs_put_int(rs_w, nms_radius)
    call rs_call(75, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> Gradient-direction-guided Hough circle transform: for every edge pixel (Sobel gradient magnitude >=
!> `gradient_threshold` on `img's` grayscale conversion), and for every candidate radius in
!> [`min_radius`, `max_radius`], votes for the two candidate centers at that distance along the pixel's
!> gradient line (handles both bright-disk-on-dark and dark-disk-on-bright edge polarity). Each radius
!> gets an independent 2D (cx, cy) accumulator and non-max suppression pass -- simpler to reason about
!> than a combined 3D (cx, cy, r) accumulator, at the cost of not suppressing near-duplicate detections
!> across adjacent radii.
!>
!> Uses the C++ default for `gradient_threshold = 5e+01`, `min_votes = 20`, `nms_radius = 10`.
!>
!> @param img
!> @param min_radius
!> @param max_radius
recursive function hough_circles_1(img, min_radius, max_radius, status) result(rs_res)
    class(Image), intent(in) :: img
    integer, intent(in) :: min_radius
    integer, intent(in) :: max_radius
    type(rosetta_error), intent(out), optional :: status
    type(HoughCircle), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, img, 0)
    call rs_put_int(rs_w, min_radius)
    call rs_put_int(rs_w, max_radius)
    call rs_call(76, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

