!> Sparse Lucas-Kanade optical flow: for each of `points`, solves the classical 2x2 windowed
!> least-squares system (built from Sobel spatial gradients Ix/Iy on `prev` and the temporal gradient
!> It = next - prev, both accumulated over a (2*window_radius+1)^2 window) for the local translation
!> (dx, dy) that best explains the window's brightness change under the standard optical-flow
!> brightness-constancy assumption. Single-level (not the pyramidal coarse-to-fine extension real
!> implementations use for large motions) -- correctly handles motions up to roughly `window_radius`
!> pixels, which is this module's documented scope tradeoff; use gaussian_pyramid() externally and call
!> this once per level if larger motions matter.
!>
!> Uses the C++ default for `window_radius = 7`.
!>
!> @param prev
!> @param next
!> @param points
recursive function lucas_kanade_optical_flow_1(prev, next, points, status) result(rs_res)
    class(Image), intent(in) :: prev
    class(Image), intent(in) :: next
    type(pair_int_int), intent(in) :: points(:)
    type(rosetta_error), intent(out), optional :: status
    type(FlowVector), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, prev, 0)
    call rs_put_object(rs_w, next, 1)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        call rs_put_list(rs_w, 2)
        call rs_put_int(rs_w, points(rs_i1)%first)
        call rs_put_int(rs_w, points(rs_i1)%second)
    end do
    call rs_call(83, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> Sparse Lucas-Kanade optical flow: for each of `points`, solves the classical 2x2 windowed
!> least-squares system (built from Sobel spatial gradients Ix/Iy on `prev` and the temporal gradient
!> It = next - prev, both accumulated over a (2*window_radius+1)^2 window) for the local translation
!> (dx, dy) that best explains the window's brightness change under the standard optical-flow
!> brightness-constancy assumption. Single-level (not the pyramidal coarse-to-fine extension real
!> implementations use for large motions) -- correctly handles motions up to roughly `window_radius`
!> pixels, which is this module's documented scope tradeoff; use gaussian_pyramid() externally and call
!> this once per level if larger motions matter.
!>
!> @param prev
!> @param next
!> @param points
!> @param window_radius
recursive function lucas_kanade_optical_flow_2(prev, next, points, window_radius, status) result(rs_res)
    class(Image), intent(in) :: prev
    class(Image), intent(in) :: next
    type(pair_int_int), intent(in) :: points(:)
    integer, intent(in) :: window_radius
    type(rosetta_error), intent(out), optional :: status
    type(FlowVector), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 4)
    call rs_put_object(rs_w, prev, 0)
    call rs_put_object(rs_w, next, 1)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        call rs_put_list(rs_w, 2)
        call rs_put_int(rs_w, points(rs_i1)%first)
        call rs_put_int(rs_w, points(rs_i1)%second)
    end do
    call rs_put_int(rs_w, window_radius)
    call rs_call(83, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

