!> The classical Gaussian pyramid: level 0 is `img` itself; each subsequent level is the previous level
!> Gaussian-blurred (sigma = `sigma`) then downsampled by 2x (bilinear resize) -- a coarse-to-fine
!> multi-resolution representation used throughout this module (e.g. as the natural foundation for a
!> pyramidal optical-flow extension, though lucas_kanade_optical_flow() itself stays single-level).
!> Stops early (producing fewer than `levels` images) if a level's dimensions would shrink below 1x1.
!> Throws std::invalid_argument for levels < 1.
!>
!> Uses the C++ default for `sigma = 1.0`.
!>
!> @param img
!> @param levels
recursive function gaussian_pyramid_1(img, levels, status) result(rs_res)
    class(Image), intent(in) :: img
    integer, intent(in) :: levels
    type(rosetta_error), intent(out), optional :: status
    type(Image), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, img, 0)
    call rs_put_int(rs_w, levels)
    call rs_call(102, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> The classical Gaussian pyramid: level 0 is `img` itself; each subsequent level is the previous level
