    call rs_call(103, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> The Laplacian pyramid: for every level except the last, level_i = (Gaussian level i) minus (Gaussian
!> level i+1 upsampled back to level i's size) -- the detail lost by blurring+downsampling at that
!> scale, re-centered at 128 (see detail::signed_difference_image()) so it stores as an ordinary image;
!> the final level is the smallest Gaussian level kept as-is (the residual low-frequency image the
!> whole pyramid was built from). Reconstructing the original from a Laplacian pyramid is the classical
!> use (progressively add each un-recentered level back onto the upsampled reconstruction-so-far) but
!> isn't implemented here -- this module only needed the decomposition direction.
!>
!> Uses the C++ default for `sigma = 1.0`.
!>
!> @param img
!> @param levels
recursive function laplacian_pyramid_1(img, levels, status) result(rs_res)
    class(Image), intent(in) :: img
    integer, intent(in) :: levels
    type(rosetta_error), intent(out), optional :: status
    type(Image), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, img, 0)
    call rs_put_int(rs_w, levels)
    call rs_call(104, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> The Laplacian pyramid: for every level except the last, level_i = (Gaussian level i) minus (Gaussian
!> level i+1 upsampled back to level i's size) -- the detail lost by blurring+downsampling at that
!> scale, re-centered at 128 (see detail::signed_difference_image()) so it stores as an ordinary image;
!> the final level is the smallest Gaussian level kept as-is (the residual low-frequency image the
!> whole pyramid was built from). Reconstructing the original from a Laplacian pyramid is the classical
!> use (progressively add each un-recentered level back onto the upsampled reconstruction-so-far) but
!> isn't implemented here -- this module only needed the decomposition direction.
!>
!> @param img
!> @param levels
!> @param sigma
recursive function laplacian_pyramid_2(img, levels, sigma, status) result(rs_res)
    class(Image), intent(in) :: img
    integer, intent(in) :: levels
    real(c_double), intent(in) :: sigma
    type(rosetta_error), intent(out), optional :: status
    type(Image), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, img, 0)
    call rs_put_int(rs_w, levels)
    call rs_put_real(rs_w, sigma)
    call rs_call(104, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
