    call rs_put_object(rs_w, img, 0)
    call rs_call(106, rs_w, rs_r, .true.)
    rs_res = rs_get_int(rs_r)
    call rs_end(rs_r, status)
end function

!> K-means color segmentation: clusters every pixel of `img` by its RGB value into `k` clusters
!> (Lloyd's algorithm, deterministic fixed-seed initialization by sampling k distinct pixels) and
!> returns a new RGB image where every pixel is replaced by its assigned cluster's mean color. Throws
!> std::invalid_argument if `k` exceeds the number of distinct pixels available to seed from.
!>
!> Uses the C++ default for `max_iterations = 20`, `seed = 42`.
!>
!> @param img
!> @param k
recursive function kmeans_segment_1(img, k, status) result(rs_res)
    class(Image), intent(in) :: img
    integer, intent(in) :: k
    type(rosetta_error), intent(out), optional :: status
    type(Image) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, img, 0)
    call rs_put_int(rs_w, k)
    call rs_call(107, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

