    call rs_start(rs_w, 2)
    call rs_put_string(rs_w, name)
    call rs_put_string(rs_w, directory)
    call rs_call(110, rs_w, rs_r, .true.)
    call rs_get_string(rs_r, rs_res)
    call rs_end(rs_r, status)
