    call rs_put_string(rs_w, url)
    call rs_put_string(rs_w, destination)
    call rs_put_string(rs_w, md5)
    call rs_call(111, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> Builds a uniform mesh of `num_elements` equal-length elements on [a, b]. Throws
!> std::invalid_argument if num_elements is 0 or b <= a.
!>
!> @param a
!> @param b
!> @param num_elements
recursive function make_uniform_mesh1d_1(a, b, num_elements, status) result(rs_res)
    real(c_double), intent(in) :: a
    real(c_double), intent(in) :: b
    integer, intent(in) :: num_elements
    type(rosetta_error), intent(out), optional :: status
    type(Mesh1D) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 3)
    call rs_put_real(rs_w, a)
    call rs_put_real(rs_w, b)
    call rs_put_int(rs_w, num_elements)
    call rs_call(112, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Evaluate squared Euclidean distance using the original double arithmetic. No finite/range
!> validation. Differences, products and sum can overflow, underflow or lose low bits; NaNs propagate
!> according to floating arithmetic.
!>
!> **Example**
!>
!> ```
!> std::cout << dm::geometry::squared_distance({0,0},{3,4}); // 25
!> ```
!>
!> See also: `distance()`.
!>
!> @param a First point.
!> @param b Second point.
!> @return Rounded squared distance, possibly infinity/NaN or underflowed zero.
recursive function squared_distance_1(a, b, status) result(rs_res)
    class(Point2D), intent(in) :: a
    class(Point2D), intent(in) :: b
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, a, 0)
    call rs_put_object(rs_w, b, 1)
    call rs_call(113, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    call rs_end(rs_r, status)
end function

!> Return sqrt(squared_distance(a,b)) with its original range limitations. A finite mathematical
!> distance may overflow through the squared intermediate; this convenience primitive performs no
!> checked hypot or input validation.
!>
!> **Example**
!>
!> ```
!> std::cout << dm::geometry::distance({0,0},{3,4}); // 5
!> ```
!>
!> See also: `squared_distance()`.
!>
!> @param a First point.
!> @param b Second point.
!> @return Rounded square root of the double-valued squared distance.
recursive function distance_1(a, b, status) result(rs_res)
    class(Point2D), intent(in) :: a
    class(Point2D), intent(in) :: b
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, a, 0)
    call rs_put_object(rs_w, b, 1)
    call rs_call(114, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    call rs_end(rs_r, status)
end function

!> Evaluate the original double determinant (b-a) cross (c-a). A positive exact determinant means
!> counterclockwise, but this approximation can cancel, overflow or underflow and its returned sign is
!> not certified. No tolerance or finite validation is applied. orientation_sign() supplies an exact
!> sign for finite stored binary64 points; this primitive remains unchanged.
!>
!> **Example**
!>
!> ```
!> std::cout << dm::geometry::cross({0,0},{1,0},{0,1}); // 1
!> ```
!>
!> See also: `orientation_sign()`.
!>
!> @param a First point.
!> @param b Second point.
!> @param c Third point.
!> @return Rounded double determinant, possibly infinity/NaN or a misleading zero.
recursive function cross_1(a, b, c, status) result(rs_res)
    class(Point2D), intent(in) :: a
    class(Point2D), intent(in) :: b
    class(Point2D), intent(in) :: c
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, a, 0)
    call rs_put_object(rs_w, b, 1)
    call rs_put_object(rs_w, c, 2)
    call rs_call(115, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    call rs_end(rs_r, status)
end function

!> Construct a complete unconstrained Delaunay triangulation with exact signs. Retains the original
!> one-vector signature and Triangle layout. Finite coordinate validation precedes even trivial
!> results. Duplicates coalesce to earliest ids; collinear/fewer-than-three distinct sites return no
!> faces. Uses Bowyer-Watson cavity replacement with symbolic hull ghosts, avoiding any finite
!> super-triangle whose proximity could remove valid narrow faces. All orientation/incircle signs are
!> exact for finite stored binary64, including subnormals/extreme scales. Cocircular ties retain
!> existing faces under the ordering in DelaunayTrace. Faces are strictly CCW, contain no ghosts and
!> reference original ids. Finite output order is canonical as documented on DelaunayTrace. No boundary
!> constraints, holes, Steiner refinement or minimum-angle guarantee is supplied. Input unchanged; O(n
!> log(n+1)+u^2 log(u+1)) worst-case work for n records/u distinct sites with ordered cavity maps and
!> full live scans; O(n+u) working/output storage, no shared state or optional resource caps.
!> Exact-predicate cost is bounded per binary64 query.
!>
!> **Example**
!>
!> ```
!> std::print("{}\n",dm::geometry::delaunay_triangulation({{0,0},{1,0},{.5,.000001}}).size()); // 1
!> ```
!>
!> **References**
!>
!> - A. Bowyer (1981), Computing Dirichlet tessellations, Computer Journal 24(2),162–166,
!>   doi:10.1093/comjnl/24.2.162.
!> - D. F. Watson (1981), Computing the n-dimensional Delaunay tessellation with application to Voronoi
!>   polytopes, Computer Journal 24(2),167–172, doi:10.1093/comjnl/24.2.167. This variant uses
!> symbolic boundary faces, exact decoded-dyadic signs, earliest duplicate identities and ordered
!> cavity edges.
!>
!> See also: `delaunay_trace()`, `incircle_sign()`.
!>
!> @param points Borrowed finite planar sites, possibly empty/duplicate/collinear.
!> @return Owned complete finite mesh of the distinct sites' convex hull, or no faces for collinearity.
!> @throws std::invalid_argument Any nonfinite coordinate, even on short input.
!> @throws std::length_error Counter arithmetic or container capacity exceeded.
!> @throws std::logic_error Internal cavity topology invariant fails; no partial mesh returned.
!> @throws std::bad_alloc Allocation fails.
recursive function delaunay_triangulation_1(points, status) result(rs_res)
    class(Point2D), intent(in) :: points(:)
    type(rosetta_error), intent(out), optional :: status
    type(Triangle), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 1)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        call rs_put_object(rs_w, points(rs_i1), -1)
    end do
    call rs_call(116, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> Capture actual symbolic-boundary cavity transitions from the same solver. No replay. Full finite
!> validation precedes the original-record cap and all allocation. max_tests bounds cumulative incircle
!> plus hull-side calls, checked before each complete live-face scan. Trace entries charge one per
!> insertion plus removed faces, boundary edges and added faces, including ghosts, checked before
!> retaining the event. Points/maps/final output and temporary cavities are excluded from that entry
!> count; caps do not bound bytes or wall time. Zero disables only an optional cap. O(sum cavity/event
!> sizes) additional history, at worst O(u^2), beyond the ordinary solver. Failure returns no partial
!> result.
!>
!> **Example**
!>
!> ```
!> const auto t=dm::geometry::delaunay_trace({{0,0},{4,0},{4,4},{0,4},{2,2}},5,10);
!> std::print("{} {}\n",t.triangles.size(),t.work.incircle_tests+t.work.hull_side_tests); // 4 10
!> ```
!>
!> **References**
!>
!> - Bowyer (1981), doi:10.1093/comjnl/24.2.162; Watson (1981), doi:10.1093/comjnl/24.2.167; records
!>   the symbolic-boundary variant rather than a geometric replay.
!>
!> See also: `DelaunayTrace`, `delaunay_triangulation()`.
!>
!> Uses the C++ default for `max_points = 1000000`, `max_tests = 10000000`, `max_entries = 1000000`.
!>
!> @param points Finite original coordinates, unchanged.
!> @return Owned points, original-id maps, finite mesh, actual events and work.
!> @throws std::invalid_argument Any nonfinite coordinate.
!> @throws std::length_error Optional cap, count arithmetic or container capacity exceeded.
!> @throws std::logic_error Internal cavity invariant fails.
!> @throws std::bad_alloc Allocation fails.
recursive function delaunay_trace_1(points, status) result(rs_res)
    class(Point2D), intent(in) :: points(:)
    type(rosetta_error), intent(out), optional :: status
    type(DelaunayTrace) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 1)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        call rs_put_object(rs_w, points(rs_i1), -1)
    end do
    call rs_call(117, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

