!> algorithms need not match across C++ libraries, so the seed is not a universal byte fixture.
!> Coincident draws are allowed and later triangulation deduplicates them. O(count) work/storage, owned
!> output, no global RNG or shared mutation.
!>
!> **Example**
!>
!> ```
!> std::print("{}\n",dm::geometry::delaunay_uniform_cloud(30).size()); // 30
!> ```
!>
!> See also: `delaunay_trace()`.
!>
!> @param count Number of original generated records, zero allowed.
!> @param seed mt19937 seed, default 20250728.
!> @param extent Positive finite square extent, default 10; checked even for count zero.
!> @param max_points Optional complete output-record cap, default 1000000; zero disables.
!> @return Owned generated points in [0,extent) on each axis.
!> @throws std::invalid_argument Nonpositive or nonfinite extent.
!> @throws std::length_error Optional count cap or container capacity exceeded before allocation.
!> @throws std::bad_alloc Allocation fails.
recursive function delaunay_uniform_cloud_4(count, seed, extent, max_points, status) result(rs_res)
    integer, intent(in) :: count
    integer, intent(in) :: seed
    real(c_double), intent(in) :: extent
    integer, intent(in) :: max_points
    type(rosetta_error), intent(out), optional :: status
    type(Point2D), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 4)
    call rs_put_int(rs_w, count)
    call rs_put_int(rs_w, seed)
    call rs_put_real(rs_w, extent)
    call rs_put_int(rs_w, max_points)
    call rs_call(119, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> Builds a structured rectangular mesh on [x0, x1] x [y0, y1]: nx * ny grid cells, each split into two
!> counterclockwise triangles, for a total of nx*ny*2 triangles and (nx+1)*(ny+1) nodes, ordered
!> row-major (x fastest, then y). Throws std::invalid_argument if nx or ny is 0, or if x1 <= x0 or y1
!> <= y0.
!>
!> @param x0
!> @param y0
!> @param x1
!> @param y1
!> @param nx
!> @param ny
recursive function make_rectangular_mesh2d_1(x0, y0, x1, y1, nx, ny, status) result(rs_res)
    real(c_double), intent(in) :: x0
    real(c_double), intent(in) :: y0
    real(c_double), intent(in) :: x1
    real(c_double), intent(in) :: y1
    integer, intent(in) :: nx
    integer, intent(in) :: ny
    type(rosetta_error), intent(out), optional :: status
    type(Mesh2D) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 6)
    call rs_put_real(rs_w, x0)
    call rs_put_real(rs_w, y0)
    call rs_put_real(rs_w, x1)
    call rs_put_real(rs_w, y1)
    call rs_put_int(rs_w, nx)
    call rs_put_int(rs_w, ny)
    call rs_call(120, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Builds a mesh over the convex hull of an arbitrary point cloud via Delaunay triangulation
!> (datamunge::geometry::delaunay_triangulation) -- useful for unstructured domains a structured grid
!> does not fit.
!>
!> @param points
recursive function make_mesh2d_from_points_1(points, status) result(rs_res)
    class(Point2D), intent(in) :: points(:)
    type(rosetta_error), intent(out), optional :: status
    type(Mesh2D) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 1)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        call rs_put_object(rs_w, points(rs_i1), -1)
    end do
    call rs_call(121, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Node indices lying on the mesh's outer boundary: every node incident to a boundary edge (an edge
!> belonging to exactly one triangle). Works generically for both a structured rectangular mesh (the
!> domain's four sides) and an unstructured Delaunay mesh (the convex hull), returned in ascending
!> order with no duplicates.
!>
!> @param mesh
recursive function boundary_nodes_1(mesh, status) result(rs_res)
    class(Mesh2D), intent(in) :: mesh
    type(rosetta_error), intent(out), optional :: status
    integer, allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_object(rs_w, mesh, 0)
    call rs_call(122, rs_w, rs_r, .true.)
    call rs_get_ints(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> The axis-aligned bounding box of `points`. Throws std::invalid_argument for an empty point set.
!>
!> @param points
recursive function bounding_box_1(points, status) result(rs_res)
