    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Return the closest point copies and finite-double distance using the checked all-pairs kernel.
!> Validates at least two finite points, visits every original i<j pair and compares widened hypot
!> distances. Equal rounded distances keep the lexicographically first index pair. Duplicates are valid
!> distinct records and can yield zero. No early stop, sorting or spatial pruning; O(n^2) work and O(1)
!> auxiliary storage. No input mutation/shared state. Widened comparison can change former false
!> zero/infinite results and last-bit ties; it is not an exact-real predicate. The old call/result
!> layout remains; indexed/traced variants retain input ids.
!>
!> **Example**
!>
!> ```
!> const auto r=dm::geometry::closest_pair({{0,0},{3,4},{0,1}});
!> std::print("{}\n",r.distance); // 1
!> ```
!>
!> See also: `closest_pair_indexed()`, `closest_pair_trace()`.
!>
!> @param points Borrowed original finite planar coordinates, length at least two.
!> @return Owned selected point copies and checked finite-double measured distance.
!> @throws std::invalid_argument If point count is too small or any coordinate is nonfinite.
!> @throws std::length_error If complete pair count cannot fit size_t.
!> @throws std::overflow_error If arithmetic/counters or the selected legacy distance cannot fit.
recursive function closest_pair_1(points, status) result(rs_res)
    class(Point2D), intent(in) :: points(:)
    type(rosetta_error), intent(out), optional :: status
    type(ClosestPairResult) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 1)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        call rs_put_object(rs_w, points(rs_i1), -1)
    end do
    call rs_call(124, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Compute Andrew's strict monotone-chain hull using exact binary64 orientation signs. Validates all
!> coordinates before internal indexed copies or sorting; the original by-value argument copy occurs at
!> the call boundary. Exact coordinate equality removes duplicates (including signed zero); the
!> earliest matching original record supplies its representation. Returns lexicographic-minimum first,
!> counterclockwise, no repeated endpoint and no collinear edge interiors.
!> Empty/singleton/two-point/collinear outputs follow ConvexHullAnalysis. O(n log n) comparisons plus
!> O(n) bounded exact-sign tests, O(n) scratch/output, no global state. The legacy by-value signature
!> is retained and has no optional caps. Other geometry routines that use cross() retain their own
!> floating contracts.
!>
!> **Example**
!>
!> ```
!> const auto h=dm::geometry::convex_hull({{0,0},{2,0},{2,2},{0,2},{1,1}});
!> std::cout << h.size(); // 4
!> ```
!>
!> **References**
!>
!> - A. M. Andrew (1979), Another efficient algorithm for convex hulls in two
!>   dimensions, https://doi.org/10.1016/0020-0190(79)90072-3 .
!>
!> See also: `convex_hull_analyze()`, `convex_hull_trace()`, `orientation_sign()`.
!>
!> @param points Finite planar records, copied by value as in the original API.
!> @return Owned strict hull of the represented coordinates.
!> @throws std::invalid_argument Any nonfinite coordinate.
!> @throws std::length_error Work/container size exhaustion.
recursive function convex_hull_1(points, status) result(rs_res)
    class(Point2D), intent(in) :: points(:)
    type(rosetta_error), intent(out), optional :: status
    type(Point2D), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 1)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        call rs_put_object(rs_w, points(rs_i1), -1)
    end do
    call rs_call(125, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> Execute the same exact-sign hull kernel with identities and actual work. Same ordering, degeneracy
!> and complexity contract as convex_hull(). Full finite validation precedes the complete max_points
!> cap and scratch allocation. No events or completed-chain snapshots are retained; event cap is
!> ignored.
!>
!> **Example**
!>
!> ```
!> const auto a=dm::geometry::convex_hull_analyze({{0,0},{1,0},{2,0}});
!> std::cout << a.hull.size() << ' ' << a.work.distinct_points; // 2 3
!> ```
!>
!> **References**
!>
!> - Andrew (1979), https://doi.org/10.1016/0020-0190(79)90072-3 .
!>
!> See also: `convex_hull()`, `ConvexHullOptions`.
!>
!> Uses the C++ default for `options`.
!>
!> @param points Finite original records; not mutated.
!> @return Owned hull, earliest original indices and actual counters.
!> @throws std::invalid_argument Nonfinite coordinate.
!> @throws std::length_error Complete point cap or work/container exhaustion.
recursive function convex_hull_analyze_1(points, status) result(rs_res)
    class(Point2D), intent(in) :: points(:)
    type(rosetta_error), intent(out), optional :: status
    type(ConvexHullAnalysis) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 1)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        call rs_put_object(rs_w, points(rs_i1), -1)
    end do
    call rs_call(126, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Execute the same exact-sign hull kernel with identities and actual work. Same ordering, degeneracy
