!>
!> See also: `convex_hull()`, `random_point_cloud()`.
!>
!> @param count Number of points, default forty.
!> @param seed Local mt19937 seed, default 20240728.
!> @param max_points Complete draw cap, default one million; zero unlimited.
!> @return Owned unsnapped normal point cloud.
!> @throws std::length_error Complete draw cap/container exhaustion.
!> @throws std::overflow_error A generated coordinate is nonfinite.
recursive function sample_gaussian_points_4(count, seed, max_points, status) result(rs_res)
    integer, intent(in) :: count
    integer, intent(in) :: seed
    integer, intent(in) :: max_points
    type(rosetta_error), intent(out), optional :: status
    type(Point2D), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 3)
    call rs_put_int(rs_w, count)
    call rs_put_int(rs_w, seed)
    call rs_put_int(rs_w, max_points)
    call rs_call(128, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> `n` colours from green through yellow and brown to near-white, as R's `terrain.colors(n)`.
!>
