!> const auto pal = dm::graphics::diverging_colors(3);
!> std::print("{} {} {}\n", pal[0].r, pal[1].g, pal[2].r);  // 33 247 178
!> ```
!>
!> **References**
!>
!> - C. Brewer, ColorBrewer 2.0 (RdBu scheme): https://colorbrewer2.org
!>
!> See also: `terrain_colors()`, `RPlot::image()`.
!>
!> @param n Number of colours (at least 1; 1 gives the white midpoint).
!> @return The palette, low (blue) to high (red).
!> @throws std::invalid_argument If `n` is 0.
recursive function diverging_colors_1(n, status) result(rs_res)
    integer, intent(in) :: n
    type(rosetta_error), intent(out), optional :: status
    type(RGB), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 1)
    call rs_put_int(rs_w, n)
    call rs_call(130, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> `n` colours of the viridis scale, from dark purple through blue and green to yellow, matching R's
!> `viridisLite::viridis(n)` at n = 10.
!>
!> Viridis is perceptually uniform, so equal steps in value look like equal steps in colour,
!> and it stays readable in greyscale and for the common forms of colour blindness. Colours are
!> interpolated linearly between viridis(10)'s ten anchors.
!>
!> **Example**
!>
!> ```
!> const auto pal = dm::graphics::viridis_colors(10);
!> std::print("{} {} {}\n", pal[0].r, pal[5].g, pal[9].b);  // 68 158 37
!> ```
!>
!> **References**
!>
!> - S. van der Walt and N. Smith (2015). "mpl colourmaps" (viridis): https://bids.github.io/colormap/
!> - viridisLite: https://sjmgarnier.github.io/viridisLite/
!>
!> See also: `value_colors()`, `terrain_colors()`.
!>
!> @param n Number of colours (at least 1).
!> @return The palette, low (purple) to high (yellow).
!> @throws std::invalid_argument If `n` is 0.
recursive function viridis_colors_1(n, status) result(rs_res)
    integer, intent(in) :: n
    type(rosetta_error), intent(out), optional :: status
    type(RGB), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 1)
    call rs_put_int(rs_w, n)
    call rs_call(131, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> One colour per value on a continuous scale, for colouring scatter points by a numeric variable
!> (ggplot2's `scale_colour_viridis_c()`).
!>
!> Each value is mapped linearly from [`z_min`, `z_max`] to the palette and rounded to the
!> nearest entry; values outside are clamped, NaN values get grey (190, 190, 190), and a zero
!> range maps everything to the middle colour. Pass the result to RPlot::points_colored().
!>
!> **Example**
!>
!> ```
!> const auto cols = dm::graphics::value_colors({0.0, 0.5, 1.0}, dm::graphics::viridis_colors(3));
!> std::print("{} {} {}\n", cols[0].r, cols[1].r, cols[2].r);  // 68 35 253
!> ```
!>
!> See also: `viridis_colors()`, `RPlot::points_colored()`.
!>
!> Uses the C++ default for `palette`, `z_min`, `z_max`.
!>
!> @param values Values to colour.
!> @return One colour per value.
recursive function value_colors_1(values, status) result(rs_res)
    real(c_double), intent(in) :: values(:)
    type(rosetta_error), intent(out), optional :: status
    type(RGB), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 1)
    call rs_put_reals(rs_w, values)
    call rs_call(132, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> One colour per value on a continuous scale, for colouring scatter points by a numeric variable
!> (ggplot2's `scale_colour_viridis_c()`).
!>
!> Each value is mapped linearly from [`z_min`, `z_max`] to the palette and rounded to the
!> nearest entry; values outside are clamped, NaN values get grey (190, 190, 190), and a zero
!> range maps everything to the middle colour. Pass the result to RPlot::points_colored().
!>
!> **Example**
!>
!> ```
!> const auto cols = dm::graphics::value_colors({0.0, 0.5, 1.0}, dm::graphics::viridis_colors(3));
!> std::print("{} {} {}\n", cols[0].r, cols[1].r, cols[2].r);  // 68 35 253
!> ```
!>
!> See also: `viridis_colors()`, `RPlot::points_colored()`.
!>
!> Uses the C++ default for `z_min`, `z_max`.
!>
!> @param values Values to colour.
!> @param palette Colours from low to high (default viridis_colors(256)).
!> @return One colour per value.
recursive function value_colors_2(values, palette, status) result(rs_res)
    real(c_double), intent(in) :: values(:)
    class(RGB), intent(in) :: palette(:)
    type(rosetta_error), intent(out), optional :: status
    type(RGB), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 2)
    call rs_put_reals(rs_w, values)
    call rs_put_list(rs_w, size(palette))
    do rs_i1 = 1, size(palette)
        call rs_put_object(rs_w, palette(rs_i1), -1)
    end do
    call rs_call(132, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> One colour per value on a continuous scale, for colouring scatter points by a numeric variable
!> (ggplot2's `scale_colour_viridis_c()`).
!>
!> Each value is mapped linearly from [`z_min`, `z_max`] to the palette and rounded to the
!> nearest entry; values outside are clamped, NaN values get grey (190, 190, 190), and a zero
!> range maps everything to the middle colour. Pass the result to RPlot::points_colored().
!>
!> **Example**
!>
!> ```
!> const auto cols = dm::graphics::value_colors({0.0, 0.5, 1.0}, dm::graphics::viridis_colors(3));
!> std::print("{} {} {}\n", cols[0].r, cols[1].r, cols[2].r);  // 68 35 253
!> ```
