!>
!> @param values Values to colour.
!> @param palette Colours from low to high (default viridis_colors(256)).
!> @param z_min Value of the first colour; NaN (the default) uses the smallest value.
!> @return One colour per value.
recursive function value_colors_3(values, palette, z_min, status) result(rs_res)
    real(c_double), intent(in) :: values(:)
    class(RGB), intent(in) :: palette(:)
    real(c_double), intent(in) :: z_min
    type(rosetta_error), intent(out), optional :: status
    type(RGB), allocatable :: rs_res(:)
