!> Clips `subject` (any simple polygon, convex or not) against `clip` (Sutherland- Hodgman) and returns
!> their intersection as a new polygon. `clip` MUST be convex AND counterclockwise-ordered (exactly
!> what convex_hull() produces) -- the algorithm processes it one directed edge at a time, keeping only
!> the subject-polygon portion to the left of every edge, so a clockwise or non-convex clip polygon
!> silently produces a wrong (or empty) result rather than an error. Returns an empty polygon if the
!> two don't overlap at all.
!>
!> @param subject
!> @param clip
recursive function clip_polygon_1(subject, clip, status) result(rs_res)
    class(Point2D), intent(in) :: subject(:)
    class(Point2D), intent(in) :: clip(:)
    type(rosetta_error), intent(out), optional :: status
    type(Point2D), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 2)
    call rs_put_list(rs_w, size(subject))
    do rs_i1 = 1, size(subject)
        call rs_put_object(rs_w, subject(rs_i1), -1)
    end do
    call rs_put_list(rs_w, size(clip))
    do rs_i1 = 1, size(clip)
        call rs_put_object(rs_w, clip(rs_i1), -1)
    end do
    call rs_call(156, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> C++ `datamunge::geometry::detail::point_in_triangle`.
