    call rs_put_object(rs_w, c, 3)
    call rs_call(157, rs_w, rs_r, .true.)
    rs_res = rs_get_bool(rs_r)
    call rs_end(rs_r, status)
end function

!> Triangulates a SIMPLE polygon (convex or not, but not self-intersecting) by ear clipping: repeatedly
!> finds a "ear" -- a convex vertex whose neighbor-triangle contains no other polygon vertex -- clips
!> it off as one output triangle, and repeats on the remaining (n-1)-vertex polygon. O(n^3) worst case
!> (each of the O(n) clipped ears requires an O(n) scan to verify, each vertex check O(1)) -- unlike
!> delaunay_triangulation() (which only sees an unordered point SET), this respects the polygon's
!> actual boundary, so it correctly handles concave (non-convex) shapes. Every triangle's vertices are
!> indices into `polygon`. Works for any winding order (detects and internally corrects clockwise
!> input). Returns empty for fewer than 3 vertices; a triangle input returns itself unchanged.
!>
!> @param polygon
recursive function triangulate_polygon_1(polygon, status) result(rs_res)
    class(Point2D), intent(in) :: polygon(:)
    type(rosetta_error), intent(out), optional :: status
    type(Triangle), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1, rs_n1
    call rs_start(rs_w, 1)
    call rs_put_list(rs_w, size(polygon))
    do rs_i1 = 1, size(polygon)
        call rs_put_object(rs_w, polygon(rs_i1), -1)
    end do
    call rs_call(158, rs_w, rs_r, .true.)
    rs_n1 = rs_get_count(rs_r)
    if (allocated(rs_res)) deallocate(rs_res)
    allocate(rs_res(rs_n1))
    do rs_i1 = 1, rs_n1
        call rs_get_object(rs_r, rs_res(rs_i1))
    end do
    call rs_end(rs_r, status)
end function

!> The diameter of a point set: the farthest pair of points, by Euclidean distance. The farthest pair
!> is always a pair of convex hull vertices, so this computes the hull first (convex_hull()) and then
!> searches only among its (typically far fewer) vertices -- brute-force O(h^2) over the hull rather
!> than the classical O(h) two-pointer rotating-calipers walk, the same "correct and simple over
!> asymptotically optimal" tradeoff this module already makes for closest_pair(). Throws
!> std::invalid_argument for fewer than 2 distinct points.
!>
!> @param points
recursive function polygon_diameter_1(points, status) result(rs_res)
    class(Point2D), intent(in) :: points(:)
    type(rosetta_error), intent(out), optional :: status
    type(DiameterResult) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 1)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        call rs_put_object(rs_w, points(rs_i1), -1)
    end do
    call rs_call(159, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> The minimum-AREA bounding rectangle of a point set (not necessarily axis-aligned). By a classical
!> theorem, the optimal rectangle always has one side collinear with a convex hull edge -- so this
!> computes the hull, then for each hull edge, measures the bounding rectangle aligned with that edge's
!> direction (projecting every hull point onto the edge direction and its perpendicular), keeping the
!> smallest-area result. O(h^2) (h = hull size): the classical rotating-calipers formulation does this
!> in O(h) via incrementally-advanced support points, but re-projecting from scratch for every edge is
!> far simpler to get right and, again, this module's established complexity/simplicity tradeoff.
!> Throws std::invalid_argument if the hull has fewer than 3 vertices (no well-defined minimum-area
!> rectangle for a degenerate point set).
!>
!> @param points
recursive function minimum_bounding_rectangle_1(points, status) result(rs_res)
    class(Point2D), intent(in) :: points(:)
    type(rosetta_error), intent(out), optional :: status
    type(MinimumBoundingRectangle) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 1)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        call rs_put_object(rs_w, points(rs_i1), -1)
    end do
    call rs_call(160, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

