!> Draws the polygon defined by `points` (in order, implicitly closed back to the first point) onto
!> `img`. Outline mode connects consecutive vertices with draw_line(); filled mode uses a standard
!> even-odd scanline fill. Fewer than 3 points draws nothing.
!>
!> Uses the C++ default for `filled = .false.`.
!>
!> @param img
!> @param points
!> @param color
recursive subroutine draw_polygon_1(img, points, color, status)
    class(Image), intent(in) :: img
    type(pair_int_int), intent(in) :: points(:)
    class(Pixel), intent(in) :: color
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 3)
    call rs_put_object(rs_w, img, 0)
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        call rs_put_list(rs_w, 2)
        call rs_put_int(rs_w, points(rs_i1)%first)
        call rs_put_int(rs_w, points(rs_i1)%second)
    end do
    call rs_put_object(rs_w, color, 2)
    call rs_call(172, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

