    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Writes `img` as an 8-bit-depth, non-interlaced PNG, using its ImageMode directly as the PNG color
!> type (Grayscale/GrayscaleAlpha/RGB/RGBA all have a direct PNG equivalent, so no conversion is ever
!> needed). Every scanline is written with filter type 0 (None) -- simpler and always correct, at the
!> cost of a somewhat larger file than a filter-optimizing encoder would produce; any standard PNG
!> decoder still reads the result correctly.
!>
!> @param img
!> @param path
recursive subroutine write_png_1(img, path, status)
    class(Image), intent(in) :: img
