    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_object(rs_w, img, 0)
    call rs_put_string(rs_w, path)
    call rs_call(180, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> Expected improvement of a Gaussian prediction below an incumbent (minimisation).
!>
!> For `Y\sim N(\mu,\sigma^2)` and target `t=\text{incumbent}-\xi`,
!> `\operatorname{E}\max(t-Y,0)=(t-\mu)\Phi(u)+\sigma\varphi(u)` with `u=(t-\mu)/\sigma`.
!>
!> `\mu`.
!>
!> `\sigma\ge0`; 0 gives `\max(t-\mu,0)`.
!>
!> `\xi\ge0` an improvement must exceed.
!>
!> **Example**
!>
!> ```
!> std::print("{:.4f}\n", dm::optim::expected_improvement(0.0, 1.0, 0.0));  // 0.3989 = phi(0)
!> ```
!>
!> Uses the C++ default for `exploration = 0.0`.
!>
!> @param mean Predicted mean
!> @param sd Predicted standard deviation
!> @param incumbent Smallest value observed so far.
!> @return The expected improvement (never negative).
recursive function expected_improvement_1(mean, sd, incumbent, status) result(rs_res)
    real(c_double), intent(in) :: mean
    real(c_double), intent(in) :: sd
    real(c_double), intent(in) :: incumbent
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 3)
    call rs_put_real(rs_w, mean)
    call rs_put_real(rs_w, sd)
    call rs_put_real(rs_w, incumbent)
    call rs_call(181, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    call rs_end(rs_r, status)
end function

!> Expected improvement of a Gaussian prediction below an incumbent (minimisation).
