!> @return statistic=D or D+/D-, parameter1=n and approximate p_value; no CI.
!> @throws std::invalid_argument Too few/nonfinite values, invalid mean/sd or alternative.
recursive function ks_test_one_sample_normal_1(x, status) result(rs_res)
    real(c_double), intent(in) :: x(:)
    type(rosetta_error), intent(out), optional :: status
    type(HypothesisTestResult) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_reals(rs_w, x)
    call rs_call(191, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

