!>
!> - https://stat.ethz.ch/R-manual/R-devel/library/stats/html/t.test.html
!>
!> See also: `HypothesisTestResult`.
!>
!> Uses the C++ default for `equal_variance = .false.`, `alternative = TwoSided`, `conf_level = 0.95`.
!>
!> @param x At least two finite observations in the first group.
!> @param y At least two finite independent observations in the second group.
!> @return statistic=t, parameter1=df, estimate1/2=group means, p_value and confidence bounds for their
!> difference. One-sided bounds can be infinite.
!> @throws std::invalid_argument Invalid sample sizes/values, alternative/confidence, unrepresentable
!> mean difference or zero/nonfinite combined standard error.
recursive function t_test_two_sample_1(x, y, status) result(rs_res)
    real(c_double), intent(in) :: x(:)
    real(c_double), intent(in) :: y(:)
    type(rosetta_error), intent(out), optional :: status
    type(HypothesisTestResult) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_reals(rs_w, x)
    call rs_put_reals(rs_w, y)
    call rs_call(202, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

