!> targets the same difference.
!> @throws std::invalid_argument Length mismatch, nonfinite data/differences, invalid controls or
!> zero/nonfinite difference standard error.
recursive function t_test_paired_1(x, y, status) result(rs_res)
    real(c_double), intent(in) :: x(:)
    real(c_double), intent(in) :: y(:)
    type(rosetta_error), intent(out), optional :: status
    type(HypothesisTestResult) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_reals(rs_w, x)
    call rs_put_reals(rs_w, y)
    call rs_call(203, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

