    type(rs_reader) :: rs_r
    call rs_start(rs_w, 4)
    call rs_put_reals(rs_w, x)
    call rs_put_reals(rs_w, y)
    call rs_put_int(rs_w, alternative)
    call rs_put_real(rs_w, conf_level)
