!> Create a directory and any missing parent directories. Accepts native filesystem paths, strings and
!> string literals. An existing directory is a successful no-op; an existing file at the target or
!> along its parents is an error. Relative paths use the current working directory, which this function
!> does not change. Permissions follow the native filesystem and process defaults. A failed recursive
!> operation may leave created parents. This C++ convenience forwards to
!> std::filesystem::create_directories().
!>
!> **Example**
!>
!> ```
!> dm::mkdir("build/figs");
!> std::print("{}\n", std::filesystem::is_directory("build/figs")); // true
!> ```
!>
!> See also: `std::filesystem::create_directories()`.
!>
!> @param path Directory to create, including any missing parents; must not be empty.
!> @return True if the target directory was created, false if it already existed.
!> @throws std::filesystem::filesystem_error For an empty path, a conflicting file, insufficient
!> permissions or other operating-system filesystem errors.
recursive function mkdir_1(path, status) result(rs_res)
    character(len=*), intent(in) :: path
    type(rosetta_error), intent(out), optional :: status
    logical :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 1)
    call rs_put_string(rs_w, path)
    call rs_call(208, rs_w, rs_r, .true.)
    rs_res = rs_get_bool(rs_r)
    call rs_end(rs_r, status)
end function

!> Prints a hello message to standard output.
recursive subroutine hello_1(status)
    type(rosetta_error), intent(out), optional :: status
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 0)
    call rs_call(209, rs_w, rs_r)
    call rs_end(rs_r, status)
end subroutine

!> Invokes a callback with the given value.
!>
!> @param x Input value passed to the callback.
!> @param cb Pointer to a `Callback` instance; must not be null.
!> @return Result of `cb->call(x)`.
recursive function call_with_callback_1(x, cb, status) result(rs_res)
    real(c_double), intent(in) :: x
    class(Callback), intent(in), optional :: cb
    type(rosetta_error), intent(out), optional :: status
    real(c_double) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_real(rs_w, x)
    if (present(cb)) then
        call rs_put_object(rs_w, cb, 1)
    else
        call rs_put_nil(rs_w)
    end if
    call rs_call(210, rs_w, rs_r, .true.)
    rs_res = rs_get_real(rs_r)
    call rs_end(rs_r, status)
end function

!> Applies a callback to every element of a vector.
!>
!> @param values Source vector of doubles.
!> @param cb Pointer to a `Callback` instance; must not be null.
!> @return New vector where each element is the result of `cb->call(v)` for the corresponding element
!> `v` in `values`.
recursive function map_dvector_with_callback_1(values, cb, status) result(rs_res)
    real(c_double), intent(in) :: values(:)
    class(Callback), intent(in), optional :: cb
    type(rosetta_error), intent(out), optional :: status
    real(c_double), allocatable :: rs_res(:)
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    call rs_start(rs_w, 2)
    call rs_put_reals(rs_w, values)
    if (present(cb)) then
        call rs_put_object(rs_w, cb, 1)
    else
        call rs_put_nil(rs_w)
    end if
    call rs_call(211, rs_w, rs_r, .true.)
    call rs_get_reals(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Constructs a three-element vector from individual values.
