            call rs_put_reals(rs_w, points(rs_i1)%v)
        end if
    end do
    call rs_put_reals(rs_w, values)
    call rs_put_object(rs_w, options, 3)
    call rs_call(236, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Fits a tensor-product P-spline: least squares plus an anisotropic difference penalty, solving (B^T B
!> + P) c = B^T y with P from tensor_difference_penalty().
!>
!> All-zero lambdas reproduce fit_tensor_bspline(). Positive lambdas keep the system
!> well-posed even with fewer points than coefficients (for order 0, or once the data
!> determine the order-q polynomial null space).
!>
!> **Example**
!>
!> ```
!> auto b = dm::fda::BSplineBasis::open_uniform(3, 8);
!> auto f = dm::fda::fit_tensor_pspline({b}, {{0.0}, {1.0}}, {0.0, 1.0}, {1e3});
!> std::print("{:.3f}\n", f.evaluate(0.5)); // 0.500
!> ```
!>
!> **References**
!>
!> - P. H. C. Eilers and B. D. Marx (1996). Flexible smoothing with B-splines and penalties.
!>   https://doi.org/10.1214/ss/1038425655
!> - P. H. C. Eilers, I. D. Currie and M. Durban (2006). Fast and compact smoothing on large
!>   multidimensional grids. https://doi.org/10.1016/j.csda.2004.07.008
!>
!> See also: `fit_tensor_bspline()`, `fit_pspline()`.
!>
!> Uses the C++ default for `order = 2`, `options`.
!>
!> @param bases One basis per dimension.
!> @param points Sample locations, each of length bases.size().
!> @param values One response per point.
!> @param lambdas Nonnegative per-axis smoothing weights, one per basis.
!> @return The fitted spline.
!> @throws std::invalid_argument On empty/mismatched inputs, invalid lambdas, or an axis with no more
!> functions than `order`.
!> @throws std::runtime_error If the penalized normal equations are singular.
recursive function fit_tensor_pspline_1(bases, points, values, lambdas, status) result(rs_res)
    class(BSplineBasis), intent(in) :: bases(:)
    type(vector_real), intent(in) :: points(:)
    real(c_double), intent(in) :: values(:)
    real(c_double), intent(in) :: lambdas(:)
    type(rosetta_error), intent(out), optional :: status
    type(TensorBSpline) :: rs_res
    type(rs_writer) :: rs_w
    type(rs_reader) :: rs_r
    integer :: rs_i1
    call rs_start(rs_w, 4)
    call rs_put_list(rs_w, size(bases))
    do rs_i1 = 1, size(bases)
        call rs_put_object(rs_w, bases(rs_i1), -1)
    end do
    call rs_put_list(rs_w, size(points))
    do rs_i1 = 1, size(points)
        if (.not. allocated(points(rs_i1)%v)) then
            call rs_put_list(rs_w, 0)
        else
            call rs_put_reals(rs_w, points(rs_i1)%v)
        end if
    end do
    call rs_put_reals(rs_w, values)
    call rs_put_reals(rs_w, lambdas)
    call rs_call(237, rs_w, rs_r, .true.)
    call rs_get_object(rs_r, rs_res)
    call rs_end(rs_r, status)
end function

!> Fits a tensor-product P-spline: least squares plus an anisotropic difference penalty, solving (B^T B
!> + P) c = B^T y with P from tensor_difference_penalty().
!>
!> All-zero lambdas reproduce fit_tensor_bspline(). Positive lambdas keep the system
!> well-posed even with fewer points than coefficients (for order 0, or once the data
!> determine the order-q polynomial null space).
!>
!> **Example**
!>
!> ```
!> auto b = dm::fda::BSplineBasis::open_uniform(3, 8);
!> auto f = dm::fda::fit_tensor_pspline({b}, {{0.0}, {1.0}}, {0.0, 1.0}, {1e3});
!> std::print("{:.3f}\n", f.evaluate(0.5)); // 0.500
!> ```
!>
!> **References**
!>
