!> @throws std::runtime_error if a downloaded dataset is not cached and cannot be fetched.
recursive function load_1(name, status) result(rs_res)
    character(len=*), intent(in) :: name
    type(rosetta_error), intent(out), optional :: status
    type(DataFrame) :: rs_res
    type(rs_writer) :: rs_w
